beach-umbrella.source:
const main = params.color;
const stripe = params.stripeColor;
const tilt = params.tilt;
const ang = tilt * Math.PI / 180;
const cs = Math.cos(ang);
const sn = Math.sin(ang);
const poleH = 2.35;
const poleR = 0.027;
const canopyR = 1.18;
const hubY = 2.16;
const tx = -sn * poleH * 0.5;
const ty = cs * poleH * 0.5;
const point = (x, y, z) => [x * cs - y * sn, x * sn + y * cs, z];
const fabric = { preset: 'fabric', roughness: 0.82, flatShading: true };
const wood = { preset: 'wood', color: '#9a673d', roughness: 0.62 };
const metal = { preset: 'metal', color: '#d8d2c3', metalness: 0.65, roughness: 0.32 };
const sand = { preset: 'sand', color: '#d9bd83', roughness: 1, flatShading: true };
api.add(api.icosphereRock(0.34, 0.32).scale(1.55, 0.28, 1.35).translate(0, 0.06, 0), sand);
api.add(api.cylinder(poleR, poleR * 1.08, poleH, 12).rotate(0, 0, tilt).translate(tx, ty, 0), wood);
const capProfile = [[0, hubY + 0.34], [canopyR * 0.2, hubY + 0.3], [canopyR * 0.48, hubY + 0.19], [canopyR * 0.76, hubY + 0.03], [canopyR, hubY - 0.16], [canopyR * 0.98, hubY - 0.22], [canopyR * 0.74, hubY - 0.04], [canopyR * 0.47, hubY + 0.12], [canopyR * 0.19, hubY + 0.24], [0, hubY + 0.28]];
const canopy = api.lathe(capProfile, 32).rotate(0, 0, tilt);
canopy.vertexColor((x, y, z) => {
  let a = Math.atan2(z, x);
  if (a < 0) a += Math.PI * 2;
  return Math.floor(a / (Math.PI / 4)) % 2 === 0 ? main : stripe;
});
api.add(canopy, fabric);
const top = point(0, hubY + 0.35, 0);
api.add(api.sphere(0.065, 1).translate(top[0], top[1], top[2]), metal);
const hub = point(0, hubY - 0.03, 0);
api.add(api.cylinder(0.065, 0.075, 0.12, 12).rotate(0, 0, tilt).translate(hub[0], hub[1], hub[2]), metal);
for (let i = 0; i < 8; i++) {
  const a = i * Math.PI / 4;
  const inner = point(Math.cos(a) * 0.07, hubY - 0.02, Math.sin(a) * 0.07);
  const edge = point(Math.cos(a) * canopyR * 0.94, hubY - 0.17, Math.sin(a) * canopyR * 0.94);
  api.add(api.tube([inner, edge], 0.012, 6), metal);
  const braceStart = point(Math.cos(a) * 0.03, hubY - 0.23, Math.sin(a) * 0.03);
  const braceEnd = point(Math.cos(a) * canopyR * 0.48, hubY + 0.06, Math.sin(a) * canopyR * 0.48);
  api.add(api.tube([braceStart, braceEnd], 0.009, 6), metal);
}
const towelW = 0.82;
const towelL = 1.48;
const towel = api.box(towelW, 0.018, towelL).translate(0.62, 0.105, 0.28);
towel.vertexColor((x, y, z) => Math.floor((z + towelL * 0.5) / (towelL / 7)) % 2 === 0 ? main : stripe);
api.add(towel, fabric);
for (let side = -1; side <= 1; side += 2) {
  for (let j = 0; j < 9; j++) {
    const x = 0.62 - towelW * 0.44 + j * towelW * 0.11;
    const z = 0.28 + side * (towelL * 0.5 + 0.045);
    api.add(api.cylinder(0.007, 0.007, 0.09, 5).rotate(90, 0, 0).translate(x, 0.105, z), { preset: 'fabric', color: stripe, roughness: 0.9 });
  }
}
api.collider({ kind: 'box', halfExtents: [0.045, poleH * 0.5, 0.045], offset: [tx, ty, 0], rotation: [0, 0, tilt] });
api.collider({ kind: 'box', halfExtents: [canopyR * 0.72, 0.18, canopyR * 0.72], offset: point(0, hubY + 0.08, 0), rotation: [0, 0, tilt] });
api.collider({ kind: 'box', halfExtents: [towelW * 0.5, 0.012, towelL * 0.5], offset: [0.62, 0.105, 0.28] });
return api.build();

castle-gate.source:
const H = params.height;
const S = H / 8;
const towerR = 1.45 * S;
const towerH = 6.9 * S;
const towerX = 3.05 * S;
const wallD = 1.9 * S;
const gateHalf = 1.15 * S;
const springY = 2.7 * S;
const archR = gateHalf;
const crownY = springY + archR;
const stone = { preset: 'stone', color: params.stoneColor, roughness: 0.92, flatShading: true };
const darkStone = { preset: 'stone', color: api.mix(params.stoneColor, '#282826', 0.32), roughness: 0.95, flatShading: true };
const iron = { preset: 'metal', color: '#25282a', metalness: 0.72, roughness: 0.42 };
const wood = { preset: 'wood', color: '#4b3120', roughness: 0.88 };
const addStone = (mesh) => {
  mesh.vertexColor((x, y, z) => api.mix(params.stoneColor, '#5d594f', 0.10 + 0.10 * (api.noise3(x * 1.7, y * 1.7, z * 1.7) + 1) * 0.5));
  api.add(mesh, stone);
};
addStone(api.cylinder(towerR * 0.96, towerR, towerH, 16).translate(-towerX, towerH / 2, 0));
addStone(api.cylinder(towerR * 0.96, towerR, towerH, 16).translate(towerX, towerH / 2, 0));
addStone(api.box(towerX * 2, springY, wallD).translate(0, springY / 2, 0));
addStone(api.box(towerX * 2, 1.7 * S, wallD).translate(0, crownY + 0.85 * S, 0));
addStone(api.box(towerX - gateHalf, crownY - springY, wallD).translate(-(towerX + gateHalf) / 2, (springY + crownY) / 2, 0));
addStone(api.box(towerX - gateHalf, crownY - springY, wallD).translate((towerX + gateHalf) / 2, (springY + crownY) / 2, 0));
const archOuter = archR + 0.38 * S;
const archSegs = 11;
for (let side = -1; side <= 1; side += 2) {
  const z = side * (wallD / 2 + 0.035 * S);
  for (let i = 0; i < archSegs; i++) {
    const a0 = i * Math.PI / archSegs;
    const a1 = (i + 1) * Math.PI / archSegs;
    const shape = [
      [Math.cos(a0) * archR, springY + Math.sin(a0) * archR],
      [Math.cos(a0) * archOuter, springY + Math.sin(a0) * archOuter],
      [Math.cos(a1) * archOuter, springY + Math.sin(a1) * archOuter],
      [Math.cos(a1) * archR, springY + Math.sin(a1) * archR]
    ];
    const voussoir = api.extrude(shape, 0.15 * S).translate(0, 0, z);
    voussoir.vertexColor(() => i % 2 === 0 ? api.mix(params.stoneColor, '#d3c9ae', 0.18) : api.mix(params.stoneColor, '#504c45', 0.12));
    api.add(voussoir, stone);
  }
}
for (let side = -1; side <= 1; side += 2) {
  addStone(api.box(0.34 * S, springY, 0.16 * S).translate(side * (gateHalf + 0.19 * S), springY / 2, wallD / 2 + 0.04 * S));
  addStone(api.box(0.34 * S, springY, 0.16 * S).translate(side * (gateHalf + 0.19 * S), springY / 2, -wallD / 2 - 0.04 * S));
}
const gateZ = wallD / 2 + 0.14 * S;
for (let i = -3; i <= 3; i++) {
  const x = i * gateHalf * 0.285;
  const top = springY + Math.sqrt(Math.max(0, archR * archR - x * x)) - 0.13 * S;
  const bottom = 0.28 * S;
  api.add(api.box(0.075 * S, top - bottom, 0.09 * S).translate(x, (top + bottom) / 2, gateZ), iron);
  api.add(api.cone(0.095 * S, 0.32 * S, 6).rotate(180, 0, 0).translate(x, bottom, gateZ), iron);
}
for (let j = 0; j < 3; j++) {
  api.add(api.box(gateHalf * 1.9, 0.085 * S, 0.11 * S).translate(0, (0.9 + j * 0.72) * S, gateZ + 0.01 * S), iron);
}
const walkY = 5.82 * S;
addStone(api.box(towerX * 2.1, 0.25 * S, wallD * 1.25).translate(0, walkY, 0));
for (let side = -1; side <= 1; side += 2) {
  const z = side * wallD * 0.69;
  addStone(api.box(towerX * 2.15, 0.34 * S, 0.24 * S).translate(0, walkY + 0.29 * S, z));
  for (let i = -4; i <= 4; i++) {
    addStone(api.box(0.45 * S, 0.58 * S, 0.34 * S).translate(i * 0.72 * S, walkY + 0.72 * S, z));
  }
}
for (let t = -1; t <= 1; t += 2) {
  addStone(api.cylinder(towerR * 1.08, towerR * 1.08, 0.25 * S, 16).translate(t * towerX, towerH + 0.02 * S, 0));
  for (let i = 0; i < 12; i++) {
    const a = i * Math.PI * 2 / 12;
    const rr = towerR * 0.96;
    addStone(api.box(0.48 * S, 0.62 * S, 0.48 * S).rotate(0, -a * 180 / Math.PI, 0).translate(t * towerX + Math.cos(a) * rr, towerH + 0.43 * S, Math.sin(a) * rr));
  }
}
for (let t = -1; t <= 1; t += 2) {
  for (let side = -1; side <= 1; side += 2) {
    api.add(api.box(0.16 * S, 0.72 * S, 0.06 * S).translate(t * towerX, 3.55 * S, side * (towerR + 0.015 * S)), darkStone);
    api.add(api.box(0.42 * S, 0.12 * S, 0.065 * S).translate(t * towerX, 3.55 * S, side * (towerR + 0.025 * S)), darkStone);
  }
}
const rearZ = -wallD / 2 - 0.09 * S;
for (let side = -1; side <= 1; side += 2) {
  api.add(api.box(0.48 * S, 1.05 * S, 0.11 * S).translate(side * 1.72 * S, 1.05 * S, rearZ), wood);
  api.add(api.box(0.07 * S, 1.08 * S, 0.13 * S).translate(side * 1.72 * S, 1.05 * S, rearZ - 0.02 * S), iron);
}
api.add(api.box(0.72 * S, 0.42 * S, 0.09 * S).translate(0, 5.12 * S, wallD / 2 + 0.07 * S), darkStone);
api.collider({ kind: 'cylinder', radius: towerR, halfHeight: towerH / 2, offset: [-towerX, towerH / 2, 0] });
api.collider({ kind: 'cylinder', radius: towerR, halfHeight: towerH / 2, offset: [towerX, towerH / 2, 0] });
api.collider({ kind: 'box', halfExtents: [(towerX - gateHalf) / 2, springY / 2, wallD / 2], offset: [-(towerX + gateHalf) / 2, springY / 2, 0] });
api.collider({ kind: 'box', halfExtents: [(towerX - gateHalf) / 2, springY / 2, wallD / 2], offset: [(towerX + gateHalf) / 2, springY / 2, 0] });
api.collider({ kind: 'box', halfExtents: [towerX, 0.85 * S, wallD / 2], offset: [0, crownY + 0.85 * S, 0] });
return api.build();

fountain.source:
const R = params.radius;
const stone = { preset: 'stone', roughness: 0.9, flatShading: true };
const basin = api.lathe([[0, 0], [R, 0], [R, R * 0.25], [R * 0.9, R * 0.25], [R * 0.9, R * 0.08], [0, R * 0.08]], 24);
basin.vertexColor((x, y, z) => api.mix(params.stoneColor, '#6f6a62', 0.25 + 0.25 * api.noise3(x * 2, y * 2, z * 2)));
api.add(basin, stone);
const water = { preset: 'water', color: params.waterColor, opacity: 0.8, roughness: 0.05, emissive: params.waterColor, emissiveIntensity: 0.15 };
api.add(api.cylinder(R * 0.9, R * 0.9, 0.04, 24).translate(0, R * 0.2, 0), water);
const pillar = api.lathe([[0, 0], [R * 0.16, 0], [R * 0.11, R * 0.4], [R * 0.13, R * 0.75], [0, R * 0.75]], 12);
pillar.vertexColor(() => params.stoneColor);
api.add(pillar, stone);
const bowl = api.lathe([[0, R * 0.7], [R * 0.45, R * 0.75], [R * 0.5, R * 0.9], [R * 0.44, R * 0.9], [R * 0.4, R * 0.8], [0, R * 0.8]], 18);
bowl.vertexColor(() => params.stoneColor);
api.add(bowl, stone);
api.add(api.cylinder(R * 0.4, R * 0.4, 0.03, 18).translate(0, R * 0.86, 0), water);
const jet = api.cone(R * 0.06, R * 0.45, 8).translate(0, R * 1.08, 0);
api.add(jet, { preset: 'water', color: '#cfefff', emissive: '#9fdcff', emissiveIntensity: 0.8, opacity: 0.7 });
api.collider({ kind: 'cylinder', radius: R, halfHeight: R * 0.125, offset: [0, R * 0.125, 0] });
api.collider({ kind: 'cylinder', radius: R * 0.16, halfHeight: R * 0.45, offset: [0, R * 0.45, 0] });
return api.build();

hero-fountain.source:
const s = params.width / 3.4;
const stoneMat = { preset: 'stone', roughness: 0.92, flatShading: true };
const waterMat = { preset: 'water', color: params.waterColor, opacity: 0.7, roughness: 0.05, emissive: params.waterColor, emissiveIntensity: 0.5 };
const sheetMat = { preset: 'water', color: '#bfe6ff', opacity: 0.45, roughness: 0.05, emissive: '#7fc8ff', emissiveIntensity: 0.8 };
function stone(m, dark) {
  m.vertexColor((x, y, z) => {
    const n = api.noise3(x * 3, y * 3, z * 3);
    let c = api.mix(params.stoneColor, '#8a6c4a', 0.2 + 0.2 * n + (dark || 0));
    if (y < 0.3) c = api.mix(c, '#5f6b45', 0.2);
    return c;
  });
  api.add(m.scale(s), stoneMat);
}
function water(m) { api.add(m.scale(s), waterMat); }
function sheet(m) { api.add(m.scale(s), sheetMat); }
// basin
stone(api.lathe([[0,0],[1.45,0],[1.55,0.08],[1.6,0.15],[1.6,0.68],[1.68,0.7],[1.72,0.76],[1.72,0.82],[1.55,0.82],[1.5,0.74],[1.45,0.7],[1.45,0.28],[0,0.28]], 8));
stone(api.cylinder(1.5, 1.55, 0.06, 8).translate(0, 0.03, 0), 0.1);
water(api.cylinder(1.43, 1.43, 0.03, 8).translate(0, 0.62, 0));
if (params.panels) {
  const ap = 1.6 * Math.cos(Math.PI / 8);
  for (let k = 0; k < 8; k++) {
    const a = 22.5 + 45 * k, r = a * Math.PI / 180;
    const px = Math.sin(r) * (ap + 0.015), pz = Math.cos(r) * (ap + 0.015);
    stone(api.box(0.8, 0.38, 0.05).rotate(0, a, 0).translate(px, 0.4, pz), -0.1);
    stone(api.box(0.6, 0.22, 0.06).rotate(0, a, 0).translate(Math.sin(r) * (ap + 0.03), 0.4, Math.cos(r) * (ap + 0.03)), 0.12);
  }
}
// pedestal
stone(api.lathe([[0,0.28],[0.5,0.28],[0.5,0.36],[0.36,0.45],[0.3,0.6],[0.24,0.7],[0.24,1.1],[0.3,1.2],[0.34,1.3],[0,1.3]], 16));
stone(api.cylinder(0.22, 0.22, 0.5, 16).translate(0, 0.9, 0));
for (let i = 0; i < 12; i++) {
  const a = i / 12 * Math.PI * 2;
  stone(api.cylinder(0.03, 0.03, 0.5, 6).translate(Math.sin(a) * 0.235, 0.9, Math.cos(a) * 0.235), 0.12);
}
// bowl 1 scalloped
const b1 = api.lathe([[0,1.25],[0.2,1.25],[0.3,1.35],[0.95,1.6],[1.0,1.66],[1.0,1.72],[0.92,1.72],[0.85,1.6],[0.2,1.45],[0,1.45]], 24);
b1.displace((x, y, z) => y > 1.4 ? 0.03 * Math.cos(Math.atan2(x, z) * 12) : 0);
stone(b1);
water(api.cylinder(0.85, 0.85, 0.03, 24).translate(0, 1.62, 0));
stone(api.cylinder(0.14, 0.16, 0.6, 12).translate(0, 1.75, 0));
// bowl 2
const b2 = api.lathe([[0,1.95],[0.12,1.95],[0.2,2.02],[0.57,2.2],[0.62,2.25],[0.62,2.3],[0.55,2.3],[0.5,2.2],[0.12,2.1],[0,2.1]], 20);
b2.displace((x, y, z) => y > 2.1 ? 0.025 * Math.cos(Math.atan2(x, z) * 10) : 0);
stone(b2);
water(api.cylinder(0.48, 0.48, 0.03, 20).translate(0, 2.2, 0));
// finial
stone(api.cylinder(0.06, 0.09, 0.5, 10).translate(0, 2.35, 0));
stone(api.cylinder(0.12, 0.1, 0.05, 10).translate(0, 2.58, 0));
const pc = api.sphere(0.17, 2).scale(1, 1.4, 1).translate(0, 2.8, 0);
pc.displace((x, y, z) => 0.025 * Math.sin(y * 40 + Math.atan2(x, z) * 6));
stone(pc, 0.05);
stone(api.cone(0.05, 0.12, 8).translate(0, 3.0, 0));
// falling sheets
for (let i = 0; i < 8; i++) {
  const a = i * 45 + 22.5, r = a * Math.PI / 180;
  sheet(api.box(0.1, 0.4, 0.012).rotate(0, a, 0).translate(Math.sin(r) * 0.63, 1.95, Math.cos(r) * 0.63));
  sheet(api.box(0.12, 1.0, 0.012).rotate(0, a, 0).translate(Math.sin(r) * 1.0, 1.12, Math.cos(r) * 1.0));
}
sheet(api.cylinder(0.025, 0.025, 0.2, 6).translate(0, 3.05, 0));
// colliders
api.collider({ kind: 'cylinder', radius: 1.7 * s, halfHeight: 0.41 * s, offset: [0, 0.41 * s, 0] });
api.collider({ kind: 'cylinder', radius: 0.3 * s, halfHeight: 0.8 * s, offset: [0, 1.0 * s, 0] });
api.collider({ kind: 'cylinder', radius: 1.0 * s, halfHeight: 0.25 * s, offset: [0, 1.5 * s, 0] });
api.collider({ kind: 'cylinder', radius: 0.6 * s, halfHeight: 0.2 * s, offset: [0, 2.15 * s, 0] });
api.collider({ kind: 'cylinder', radius: 0.1 * s, halfHeight: 0.4 * s, offset: [0, 2.6 * s, 0] });
return api.build();

laundry-line.source:
const L=params.length;
const pts=[];for(let k=0;k<=10;k++){const x=-L/2+L*k/10;pts.push([x,1.0-0.35*(1-Math.pow(2*k/10-1,2))*0.9,0]);}
api.add(api.tube(pts,0.015,4),{color:'#d8d2c4',roughness:0.9});
const cl=['#f4f1ea','#d9534f','#4a7fb5','#f0c75e','#6aa86a','#e8a0b4','#ffffff','#7a5aa0'];
const n=Math.max(3,Math.round(L/0.9));
for(let i=0;i<n;i++){const x=-L/2+0.5+(L-1)*(i+0.5)/n;const t=2*(x+L/2)/L-1;const y=1.0-0.315*(1-t*t);
 const h=0.5+api.rng()*0.45,w=0.35+api.rng()*0.4;
 api.add(api.box(w,h,0.015).translate(x,y-h/2-0.02,0.0),{color:cl[Math.floor(api.rng()*cl.length)],roughness:0.95});}
api.add(api.box(0.05,0.05,0.05).translate(-L/2,1.0,0),{color:'#333'});
api.add(api.box(0.05,0.05,0.05).translate(L/2,1.0,0),{color:'#333'});
return api.build();

lisbon-church.source:
const W = params.width, D = params.depth, H = params.towerHeight;
const wallH = 11, T = 4.5;
const rh = 0.35 * (W / 2 + 0.5);
const slope = rh / (W / 2 + 0.5);

const wallMat = { finish: 'plaster', color: params.wallColor };
const wallMat2 = { finish: 'plaster', color: api.mix(params.wallColor, '#e6d2a8', 0.5) };
const trimMat = { finish: 'limestone', color: params.trimColor };
const trimMatB = { finish: 'limestone', color: api.mix(params.trimColor, '#c79a40', 0.35) };
const roofMat = { finish: 'roof-tile', color: params.roofColor };
const domeMat = { finish: 'metal-roof', color: '#7a8a84', doubleSided: true };
const iron = { finish: 'black-metal', color: '#25272a' };
const glassMat = { preset: 'glass', color: '#4d6e82', opacity: 0.8, roughness: 0.1 };
const darkMat = { finish: 'slate', color: '#2a2623' };
const woodMat = { finish: 'oak', color: '#5a3a22' };
const cobbleMat = { finish: 'cobble', color: '#a39a8c' };
const baseMat = { finish: 'stone', color: '#b5ab98' };
const clockMat = { finish: 'plaster', color: '#f3efe4' };

function put(m, lx, ly, lz, x, y, z, yaw) {
  m.translate(lx, ly, lz);
  if (yaw) m.rotate(0, yaw, 0);
  m.translate(x, y, z);
  return m;
}

// arched opening, local frame faces +Z, wall surface at local z = 0
function opening(x, y, z, yaw, w, h, kind) {
  const r = w / 2, sh = h - r;
  const fr = w > 1.2 ? 0.28 : 0.18;
  const fw = w + 2 * fr;
  const A = (m, mat, lx, ly, lz) => api.add(put(m, lx, ly, lz, x, y, z, yaw), mat);
  A(api.roundedBox(fw, sh, 0.16, 0.04), trimMat, 0, sh / 2, 0.08);
  A(api.cylinder(fw / 2, fw / 2, 0.16, 18).rotate(90, 0, 0), trimMat, 0, sh, 0.08);
  A(api.roundedBox(0.34, 0.5, 0.26, 0.04), trimMatB, 0, sh + fw / 2 - 0.1, 0.1);
  if (kind !== 'door') A(api.roundedBox(fw + 0.3, 0.14, 0.4, 0.04), trimMatB, 0, -0.07, 0.15);
  if (kind === 'door') {
    const lh = h * 0.7;
    A(api.box(w, lh, 0.1), woodMat, 0, lh / 2, 0.09);
    const fl = sh - lh;
    A(api.box(w, fl, 0.1), glassMat, 0, lh + fl / 2, 0.09);
    A(api.cylinder(r, r, 0.1, 16).rotate(90, 0, 0), glassMat, 0, sh, 0.09);
    A(api.box(0.05, lh, 0.04), iron, 0, lh / 2, 0.16);
    A(api.box(w, 0.05, 0.04), iron, 0, lh, 0.16);
    for (let i = 0; i < 2; i++) {
      const sx = i === 0 ? -1 : 1;
      A(api.roundedBox(w / 2 - 0.3, lh * 0.36, 0.05, 0.02), woodMat, sx * w / 4, lh * 0.25, 0.14);
      A(api.roundedBox(w / 2 - 0.3, lh * 0.3, 0.05, 0.02), woodMat, sx * w / 4, lh * 0.73, 0.14);
      A(api.sphere(0.05, 1), iron, sx * 0.14, lh * 0.5, 0.18);
    }
  } else {
    const mat = kind === 'dark' ? darkMat : glassMat;
    A(api.box(w, sh, 0.1), mat, 0, sh / 2, 0.09);
    A(api.cylinder(r, r, 0.1, 16).rotate(90, 0, 0), mat, 0, sh, 0.09);
    if (kind === 'dark') {
      const n = 4;
      for (let i = 0; i < n; i++) {
        A(api.box(w, 0.09, 0.14), woodMat, 0, 0.3 + i * (sh - 0.3) / n, 0.12);
      }
      A(api.box(0.18, 0.5, 0.18), iron, 0, sh + r * 0.35, 0.06);
    } else {
      A(api.box(0.05, h - 0.1, 0.04), iron, 0, h / 2, 0.15);
      A(api.box(w, 0.05, 0.04), iron, 0, sh * 0.45, 0.15);
      A(api.box(w, 0.05, 0.04), iron, 0, sh, 0.15);
    }
  }
}

// ---------- paving apron ----------
const annexW = 4, annexD = 7.5, annexZ = -1.5, annexH = 4.5;
const px0 = -(W / 2 + T + 2.5), px1 = W / 2 + annexW + 2.5;
const pz0 = -D / 2 - 4.5, pz1 = D / 2 + 4.5;
api.add(api.roundedBox(px1 - px0, 0.12, pz1 - pz0, 0.03).translate((px0 + px1) / 2, 0.06, (pz0 + pz1) / 2), cobbleMat);

// ---------- nave ----------
api.add(api.roundedBox(W, wallH, D, 0.1).translate(0, wallH / 2, 0), wallMat);
api.add(api.roundedBox(W + 0.3, 0.7, D + 0.3, 0.06).translate(0, 0.35, 0), baseMat);

// roof
const roof = api.extrude([[-(W / 2 + 0.5), 0], [W / 2 + 0.5, 0], [0, rh]], D).translate(0, wallH, 0);
api.add(roof, roofMat);
api.add(api.cylinder(0.25, 0.25, D + 0.2, 8).rotate(90, 0, 0).translate(0, wallH + rh + 0.05, 0), roofMat);
// eave fascia
for (let s = -1; s <= 1; s += 2) {
  api.add(api.roundedBox(0.3, 0.3, D + 0.1, 0.05).translate(s * (W / 2 + 0.45), wallH + 0.02, 0), trimMat);
}

// cornices
api.add(api.roundedBox(W + 0.5, 0.5, 0.8, 0.06).translate(0, wallH - 0.25, D / 2 + 0.1), trimMat);
api.add(api.roundedBox(W + 0.5, 0.5, 0.7, 0.06).translate(0, wallH - 0.25, -D / 2), trimMat);
for (let s = -1; s <= 1; s += 2) {
  api.add(api.roundedBox(0.7, 0.5, D + 0.5, 0.06).translate(s * (W / 2), wallH - 0.25, 0), trimMat);
}

// pediment (front) and back gable
const phw = W / 2 + 0.2;
const ph = slope * phw;
const pedShape = [[-phw, 0], [phw, 0], [0, ph]];
api.add(api.extrude(pedShape, 0.4).translate(0, wallH, D / 2 + 0.2), wallMat2);
api.add(api.extrude(pedShape, 0.3).translate(0, wallH, -D / 2 - 0.15), wallMat);
const rakeLen = Math.sqrt(phw * phw + ph * ph) + 0.3;
const rakeAng = Math.atan2(ph, phw) * 180 / Math.PI;
for (let s = -1; s <= 1; s += 2) {
  api.add(api.roundedBox(rakeLen, 0.3, 0.6, 0.06).rotate(0, 0, -s * rakeAng).translate(s * phw / 2, wallH + ph / 2 + 0.12, D / 2 + 0.25), trimMat);
  api.add(api.roundedBox(rakeLen, 0.25, 0.5, 0.06).rotate(0, 0, -s * rakeAng).translate(s * phw / 2, wallH + ph / 2 + 0.1, -D / 2 - 0.15), trimMat);
}
// oculus
api.add(api.torus(0.75, 0.1).translate(0, wallH + ph * 0.36, D / 2 + 0.42), trimMat);
api.add(api.cylinder(0.68, 0.68, 0.1, 18).rotate(90, 0, 0).translate(0, wallH + ph * 0.36, D / 2 + 0.38), glassMat);
api.add(api.box(1.4, 0.04, 0.04).translate(0, wallH + ph * 0.36, D / 2 + 0.46), iron);
api.add(api.box(0.04, 1.4, 0.04).translate(0, wallH + ph * 0.36, D / 2 + 0.46), iron);
// apex finial: urn + cross
const urn = api.lathe([[0, 0], [0.3, 0], [0.18, 0.2], [0.36, 0.55], [0.2, 0.8], [0.1, 0.9], [0, 0.9]], 10);
api.add(urn.translate(0, wallH + ph + 0.2, D / 2 + 0.25), trimMat);
api.add(api.box(0.07, 0.9, 0.07).translate(0, wallH + ph + 1.55, D / 2 + 0.25), iron);
api.add(api.box(0.5, 0.07, 0.07).translate(0, wallH + ph + 1.75, D / 2 + 0.25), iron);
for (let s = -1; s <= 1; s += 2) {
  const u = api.lathe([[0, 0], [0.22, 0], [0.12, 0.15], [0.26, 0.4], [0.12, 0.6], [0, 0.65]], 10);
  api.add(u.translate(s * (phw - 0.1), wallH + 0.3, D / 2 + 0.25), trimMatB);
}

// front pilasters
const px = Math.max(1.95, W * 0.17);
const cx = W / 2 - 0.4;
const pil = [-cx, -px, px, cx];
for (let i = 0; i < 4; i++) {
  const x = pil[i];
  const m = i % 2 === 0 ? trimMat : trimMatB;
  api.add(api.roundedBox(0.62, wallH - 1.6, 0.34, 0.05).translate(x, 0.8 + (wallH - 1.6) / 2, D / 2 + 0.17), m);
  api.add(api.roundedBox(0.84, 0.45, 0.46, 0.06).translate(x, 0.5, D / 2 + 0.23), m);
  api.add(api.roundedBox(0.86, 0.4, 0.46, 0.06).translate(x, wallH - 1.0, D / 2 + 0.23), m);
  api.add(api.roundedBox(0.7, 0.15, 0.4, 0.04).translate(x, wallH - 0.75, D / 2 + 0.2), m);
}
// string course across facade
api.add(api.roundedBox(W + 0.2, 0.25, 0.4, 0.05).translate(0, 4.9, D / 2 + 0.2), trimMat);

// facade openings
const sx = W * 0.33;
opening(0, 0.45, D / 2, 0, 2.2, 4.1, 'door');
opening(0, 6.2, D / 2, 0, 1.3, 3.4, 'glass');
opening(-sx, 6.2, D / 2, 0, 1.3, 3.4, 'glass');
opening(sx, 6.2, D / 2, 0, 1.3, 3.4, 'glass');
opening(-sx, 1.5, D / 2, 0, 0.9, 2.0, 'glass');
opening(sx, 1.5, D / 2, 0, 0.9, 2.0, 'glass');
// door hood
api.add(api.roundedBox(3.2, 0.25, 0.7, 0.05).translate(0, 4.75, D / 2 + 0.3), trimMat);
// steps
for (let i = 0; i < 3; i++) {
  const lvl = 0.15 * (i + 1);
  const sw = 4.4 - i * 0.5;
  const sd = 0.5 + (2 - i) * 0.45;
  api.add(api.roundedBox(sw, lvl, sd, 0.03).translate(0, lvl / 2, D / 2 + sd / 2 - 0.05), baseMat);
}

// side windows
const nz = 3;
const zStart = -D / 2 + 2.2, zEnd = D / 2 - T - 1.2;
const zs = [];
for (let i = 0; i < nz; i++) zs.push(zStart + i * (zEnd - zStart) / (nz - 1));
for (let i = 0; i < nz; i++) {
  opening(W / 2, 6.0, zs[i], 90, 1.1, 3.2, 'glass');
  opening(-W / 2, 6.0, zs[i], -90, 1.1, 3.2, 'glass');
  opening(-W / 2, 1.8, zs[i], -90, 0.7, 1.4, 'glass');
}
// side buttress strips
const sz = [-D / 2 + 0.4];
for (let i = 0; i < nz - 1; i++) sz.push((zs[i] + zs[i + 1]) / 2);
sz.push(zs[nz - 1] + 1.9);
for (let i = 0; i < sz.length; i++) {
  for (let s = -1; s <= 1; s += 2) {
    const m = (i + (s > 0 ? 1 : 0)) % 2 === 0 ? trimMat : trimMatB;
    api.add(api.roundedBox(0.3, wallH - 1.0, 0.5, 0.05).translate(s * (W / 2 + 0.1), 0.5 + (wallH - 1.0) / 2 - 0.0, sz[i]), m);
  }
}

// ---------- apse ----------
const apz = -D / 2 + 0.4;
api.add(api.cylinder(3.2, 3.2, 8.5, 16).translate(0, 4.25, apz), wallMat);
api.add(api.cylinder(3.35, 3.35, 0.45, 16).translate(0, 8.3, apz), trimMat);
api.add(api.cylinder(3.35, 3.35, 0.7, 16).translate(0, 0.35, apz), baseMat);
api.add(api.cone(3.7, 2.6, 16).translate(0, 8.5 + 1.3, apz), roofMat);

// ---------- annex ----------
const ax0 = W / 2 - 0.1;
api.add(api.roundedBox(annexW + 0.1, annexH, annexD, 0.08).translate(ax0 + (annexW + 0.1) / 2, annexH / 2, annexZ), wallMat2);
api.add(api.roundedBox(annexW + 0.3, 0.7, annexD + 0.2, 0.05).translate(ax0 + (annexW + 0.3) / 2 - 0.1, 0.35, annexZ), baseMat);
api.add(api.roundedBox(annexW + 0.5, 0.3, annexD + 0.4, 0.05).translate(ax0 + (annexW + 0.5) / 2 - 0.05, annexH - 0.1, annexZ), trimMat);
const infill = api.extrude([[ax0, annexH], [W / 2 + annexW, annexH], [W / 2 + annexW, annexH + 0.12], [ax0, annexH + 0.9]], annexD - 0.2).translate(0, 0, annexZ);
api.add(infill, wallMat2);
const dy = 0.9 - 0.12;
const ang = Math.atan2(dy, annexW + 0.5) * 180 / Math.PI;
const slabLen = Math.sqrt((annexW + 0.5) * (annexW + 0.5) + dy * dy) + 0.2;
api.add(api.roundedBox(slabLen, 0.22, annexD + 0.7, 0.04).rotate(0, 0, -ang).translate(ax0 + (annexW + 0.5) / 2, annexH + 0.56, annexZ), roofMat);
opening(ax0 + annexW / 2 + 0.05, 0.2, annexZ + annexD / 2, 0, 1.3, 2.6, 'door');
opening(W / 2 + annexW, 1.7, annexZ - 1.8, 90, 0.9, 1.8, 'glass');
opening(W / 2 + annexW, 1.7, annexZ + 1.8, 90, 0.9, 1.8, 'glass');
opening(ax0 + annexW / 2 + 0.05, 1.7, annexZ - annexD / 2, 180, 0.9, 1.8, 'glass');

// ---------- bell tower ----------
const tx = -(W / 2 + T / 2 - 0.3);
const tz = D / 2 - T / 2 + 0.2;
const shaftTop = H - 6.6;
const b = shaftTop - 4.6;
api.add(api.roundedBox(T, shaftTop, T, 0.06).translate(tx, shaftTop / 2, tz), wallMat);
api.add(api.roundedBox(T + 0.45, 1.0, T + 0.45, 0.06).translate(tx, 0.5, tz), baseMat);
// quoins
for (let i = 0; i < 4; i++) {
  const qx = (i % 2 === 0 ? -1 : 1) * (T / 2 - 0.1);
  const qz = (i < 2 ? -1 : 1) * (T / 2 - 0.1);
  api.add(api.roundedBox(0.55, shaftTop - 1.2, 0.55, 0.05).translate(tx + qx, 1.0 + (shaftTop - 1.2) / 2 - 0.0, tz + qz), i % 2 === 0 ? trimMat : trimMatB);
}
// string courses
const courses = [5.3, b];
if (b > 12.2) courses.push(b - 5.5 > 9.7 ? 9.8 : -1);
for (let i = 0; i < courses.length; i++) {
  if (courses[i] < 0) continue;
  api.add(api.roundedBox(T + 0.55, 0.35, T + 0.55, 0.06).translate(tx, courses[i], tz), trimMat);
}
// crown cornice
api.add(api.roundedBox(T + 0.9, 0.35, T + 0.9, 0.06).translate(tx, shaftTop - 0.5, tz), trimMat);
api.add(api.roundedBox(T + 0.7, 0.3, T + 0.7, 0.06).translate(tx, shaftTop - 0.15, tz), trimMatB);
api.add(api.roundedBox(T + 0.35, 0.22, T + 0.35, 0.05).translate(tx, shaftTop + 0.11, tz), trimMat);
// openings on tower faces
const faces = [[0, 0, T / 2], [90, T / 2, 0], [180, 0, -T / 2], [-90, -T / 2, 0]];
for (let i = 0; i < 4; i++) {
  const f = faces[i];
  opening(tx + f[1], b + 0.6, tz + f[2], f[0], 1.5, 3.2, 'dark');
}
// slit windows
const win2 = b - 2.8 > 9.4;
const slitFaces = [faces[0], faces[3]];
for (let i = 0; i < 2; i++) {
  const f = slitFaces[i];
  opening(tx + f[1], 2.4, tz + f[2], f[0], 0.8, 2.4, 'glass');
  if (win2) opening(tx + f[1], 6.8, tz + f[2], f[0], 0.8, 2.4, 'glass');
}
// side door of tower
opening(tx - T / 2, 0.2, tz, -90, 1.2, 2.6, 'door');
// clock on the front
const cy = b - 1.9;
api.add(api.cylinder(0.75, 0.75, 0.08, 24).rotate(90, 0, 0).translate(tx, cy, tz + T / 2 + 0.04), clockMat);
api.add(api.torus(0.78, 0.07).translate(tx, cy, tz + T / 2 + 0.06), iron);
api.add(api.box(0.05, 0.5, 0.03).translate(tx, cy + 0.2, tz + T / 2 + 0.11), iron);
api.add(api.box(0.05, 0.36, 0.03).rotate(0, 0, -70).translate(tx + 0.15, cy - 0.04, tz + T / 2 + 0.11), iron);

// ---------- cupola ----------
const y0 = shaftTop + 0.22;
for (let i = 0; i < 4; i++) {
  const qx = (i % 2 === 0 ? -1 : 1) * (T / 2 - 0.1);
  const qz = (i < 2 ? -1 : 1) * (T / 2 - 0.1);
  api.add(api.roundedBox(0.4, 0.5, 0.4, 0.04).translate(tx + qx, y0 + 0.25, tz + qz), trimMat);
  api.add(api.cone(0.3, 0.7, 8).translate(tx + qx, y0 + 0.85, tz + qz), domeMat);
  api.add(api.sphere(0.07, 1).translate(tx + qx, y0 + 1.25, tz + qz), iron);
}
api.add(api.cylinder(1.75, 1.75, 1.0, 8).translate(tx, y0 + 0.5, tz), wallMat);
api.add(api.cylinder(1.98, 1.98, 0.2, 8).translate(tx, y0 + 0.1, tz), trimMat);
api.add(api.cylinder(1.98, 1.98, 0.18, 8).translate(tx, y0 + 1.0, tz), trimMat);
for (let i = 0; i < 8; i++) {
  const a = (i + 0.5) / 8 * Math.PI * 2;
  const r = 1.73;
  api.add(api.box(0.55, 0.7, 0.12).rotate(0, -a * 180 / Math.PI + 90, 0).translate(tx + Math.cos(a) * r, y0 + 0.55, tz + Math.sin(a) * r), darkMat);
}
const dome = api.lathe([[1.95, 0], [2.0, 0.12], [1.8, 0.5], [1.45, 1.0], [0.95, 1.5], [0.6, 1.85], [0.5, 2.0], [0, 2.05]], 8);
api.add(dome.translate(tx, y0 + 1.09, tz), domeMat);
const ly = y0 + 1.09 + 2.0;
api.add(api.cylinder(0.65, 0.65, 0.15, 8).translate(tx, ly + 0.07, tz), trimMat);
api.add(api.cylinder(0.48, 0.48, 1.0, 8).translate(tx, ly + 0.65, tz), glassMat);
for (let i = 0; i < 8; i++) {
  const a = i / 8 * Math.PI * 2;
  api.add(api.box(0.1, 1.0, 0.1).translate(tx + Math.cos(a) * 0.55, ly + 0.65, tz + Math.sin(a) * 0.55), trimMat);
}
api.add(api.cylinder(0.7, 0.7, 0.14, 8).translate(tx, ly + 1.22, tz), trimMat);
const cap = api.lathe([[0.7, 0], [0.6, 0.25], [0.32, 0.55], [0.1, 0.78], [0, 0.82]], 8);
api.add(cap.translate(tx, ly + 1.29, tz), domeMat);
api.add(api.sphere(0.13, 2).translate(tx, ly + 2.15, tz), iron);
api.add(api.box(0.07, 1.3, 0.07).translate(tx, ly + 2.75, tz), iron);
api.add(api.box(0.65, 0.07, 0.07).translate(tx, ly + 2.95, tz), iron);
api.add(api.box(0.07, 0.07, 0.65).translate(tx, ly + 2.95, tz), iron);

// ---------- colliders ----------
api.collider({ kind: 'box', halfExtents: [px1 / 2 - px0 / 2, 0.06, (pz1 - pz0) / 2], offset: [(px0 + px1) / 2, 0.06, (pz0 + pz1) / 2] });
const nh = wallH + rh * 0.5;
api.collider({ kind: 'box', halfExtents: [W / 2, nh / 2, D / 2], offset: [0, nh / 2, 0] });
api.collider({ kind: 'box', halfExtents: [T / 2, H / 2, T / 2], offset: [tx, H / 2, tz] });
api.collider({ kind: 'box', halfExtents: [annexW / 2 + 0.1, (annexH + 0.8) / 2, annexD / 2], offset: [ax0 + annexW / 2 + 0.1, (annexH + 0.8) / 2, annexZ] });
api.collider({ kind: 'cylinder', radius: 3.2, halfHeight: 5, offset: [0, 5, apz] });
api.collider({ kind: 'box', halfExtents: [2.2, 0.225, 0.9], offset: [0, 0.225, D / 2 + 0.8] });

return api.build();

