const ST=[
{p:[[-34,98],[-70,96],[-105,92],[-135,84],[-150,72],[-140,62],[-110,60],[-80,56],[-50,52],[-14,47]],w:3.2,pv:1.6},
{p:[[34,98],[72,97],[108,90],[138,80],[152,66],[138,56],[105,54],[75,50],[48,48],[14,47]],w:3.2,pv:1.6},
{p:[[-14,42],[-50,38],[-90,34],[-125,28],[-148,16],[-138,4],[-105,-2],[-70,-6],[-40,-14],[-30,-20]],w:3.2,pv:1.6},
{p:[[14,42],[52,38],[92,32],[128,26],[150,14],[140,2],[105,-4],[70,-8],[42,-16],[32,-20]],w:3.2,pv:1.6},
{p:[[0,36],[-16,30],[-24,20],[-12,11],[0,4],[0,-26]],w:3,pv:1.4},
{p:[[0,86],[0,57]],w:3.5,pv:2.2},
{p:[[-98,93],[-104,62]],w:1.6,pv:0.8},
{p:[[-6,76],[-40,77],[-80,74],[-120,70]],w:3,pv:1.5},
{p:[[-230,120],[-120,120],[0,120],[120,120],[230,120]],w:5.6,pv:3},
{p:[[-60,95],[-62,54]],w:1.4,pv:0.8},
{p:[[64,96],[60,52]],w:1.4,pv:0.8},
{p:[[6,74],[46,75],[88,72],[125,68]],w:3,pv:1.5}];
const SEG=[];ST.forEach((s,i)=>{let L=0;s.cum=[0];for(let k=1;k<s.p.length;k++){L+=Math.hypot(s.p[k][0]-s.p[k-1][0],s.p[k][1]-s.p[k-1][1]);s.cum.push(L);}s.L=L;for(let k=1;k<s.p.length;k++)SEG.push([s.p[k-1][0],s.p[k-1][1],s.p[k][0],s.p[k][1],i]);});
function near(x,z){let bd=1e9,bx=0,bz=0,bi=-1;for(const g of SEG){const dx=g[2]-g[0],dz=g[3]-g[1];let t=((x-g[0])*dx+(z-g[1])*dz)/(dx*dx+dz*dz);t=t<0?0:t>1?1:t;const px=g[0]+dx*t,pz=g[1]+dz*t,d=(x-px)*(x-px)+(z-pz)*(z-pz);if(d<bd){bd=d;bx=px;bz=pz;bi=g[4];}}return {d:Math.sqrt(bd),x:bx,z:bz,i:bi};}
const LH=base(0,46);
const padc=(h,x,z,cx,cz,r0,r1,hh)=>h+(hh-h)*(1-sm(r0,r1,Math.hypot(x-cx,z-cz)));
function H(x,z){let h=base(x,z);
 if(x>-260&&x<260&&z>-60&&z<126.5){const n=near(x,z),st=ST[n.i],W=st.w+st.pv+0.8;if(n.d<W+9){const hc=base(n.x,n.z);h+=(hc-h)*(1-sm(W,W+9,n.d));}}
 h=padc(h,x,z,0,46,9,22,LH);h=padc(h,x,z,0,2,10,26,39.0);
 let d=Math.hypot(Math.max(0,Math.abs(x)-34),Math.max(0,-68-z,z+22));h+=(39.6-h)*(1-sm(0,18,d));
 d=Math.hypot(Math.max(0,Math.abs(x)-38),Math.max(0,86-z,z-112));const hp=lin(PZ,z)*(1-0.4*sm(70,240,Math.abs(x)));h+=(hp-h)*(1-sm(0,7,d));
 return h;}
function at(si,s){const st=ST[si];s=Math.max(0,Math.min(st.L,s));let k=1;while(k<st.p.length-1&&st.cum[k]<s)k++;const a=st.p[k-1],b=st.p[k],l=st.cum[k]-st.cum[k-1],t=(s-st.cum[k-1])/l;return [a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,(b[0]-a[0])/l,(b[1]-a[1])/l];}
const part=params.part|0;
const G={};const addG=(k,m)=>{if(G[k])G[k].merge(m);else G[k]=m;};
function ribbon(k,si,s0,s1,off,wid,thick,raise,cols,step){
 for(let s=s0;s<s1-0.01;s+=step){const e=Math.min(s+step,s1),A=at(si,s),Bq=at(si,e);
  let dx=Bq[0]-A[0],dz=Bq[1]-A[1];const len=Math.hypot(dx,dz);dx/=len;dz/=len;const nx=-dz,nz=dx;
  const ax=A[0]+nx*off,az=A[1]+nz*off,bx=Bq[0]+nx*off,bz=Bq[1]+nz*off;
  const ya=H(ax,az)+raise,yb=H(bx,bz)+raise,l3=Math.hypot(len,yb-ya);
  const pitch=Math.atan2(yb-ya,len)*180/Math.PI,yaw=Math.atan2(-dz,dx)*180/Math.PI;
  const c=cols[Math.floor(hs(s*3.1,si*7+off)*cols.length)%cols.length];
  addG(k,api.box(l3*1.04,thick,wid).rotate(0,0,pitch).rotate(0,yaw,0).translate((ax+bx)/2,(ya+yb)/2-thick/2,(az+bz)/2).vertexColor(()=>c));}}
function street(si){const st=ST[si],q=si===8;
 const step=q?15:3.5;
 ribbon('road',si,0,st.L,0,st.w*2,0.6,0.08,q?['#77716a','#7d776f']:['#9a9080','#8e8576','#a39a88'],step);
 for(const sd of [-1,1])ribbon('pave',si,0,st.L,sd*(st.w+st.pv/2),st.pv,0.6,0.26,['#d8cdb6','#cfc3aa','#dcd2bd'],step);
 const sp=q?30:26;let n=0;for(let s=sp/2;s<st.L-2;s+=sp){const sd=(n++%2)?1:-1,P=at(si,s),nx=-P[3],nz=P[2],off=sd*(st.w+st.pv-0.35),x=P[0]+nx*off,z=P[1]+nz*off,y=H(x,z)+0.26;
  addG('pole',api.cylinder(0.05,0.09,3.8,6).translate(x,y+1.9,z));addG('lamp',api.box(0.28,0.42,0.28).translate(x,y+4.0,z));addG('pole',api.box(0.4,0.06,0.4).translate(x,y+4.25,z));}
}
function railLine(si,s0,s1,off,step){ribbon('bed',si,s0,s1,off,2.3,0.4,0.12,['#554a40'],step);for(const sd of [-1,1])ribbon('rail',si,s0,s1,off+sd*0.72,0.08,0.2,0.2,['#8f8f95'],step);}
function plaza(cx,cz,w,d,n,m,raise,pal,tile){const hf=api.heightfield(n,m,w,d,(x,z)=>H(x+cx,z+cz)+raise);
 hf.vertexColor((x,y,z)=>{const t=(Math.floor((x+cx)/tile)+Math.floor((z+cz)/tile))%2===0;return t?pal[0]:pal[1];});addG('plaza',hf.translate(cx,0,cz));}
if(part===0){
 for(const si of [8,5,4,0,1])street(si);
 railLine(8,0,460,1.0,15);
 railLine(1,2,86,0,3.5);
 addG('wall',api.box(470,3.4,0.6).translate(0,-1.4,128.9));
 addG('wallcap',api.box(470,0.25,0.9).translate(0,0.45,128.9));
 plaza(0,99,76,26,39,14,0.12,['#e2d8c0','#c9bda2'],3);
 plaza(0,46,20,20,11,11,0.12,['#ddd2ba','#c4b89e'],2.5);
 plaza(0,-4,26,18,14,10,0.12,['#d8ceb6','#bfb298'],2.5);
} else {
 for(const si of [2,3,7,11])street(si);
 for(const si of [6,9,10]){const st=ST[si];for(let s=0.3;s<st.L;s+=0.55){const P=at(si,s),x=P[0],z=P[1],yaw=Math.atan2(-P[3],P[2])*180/Math.PI,top=Math.round(H(x,z)/0.17)*0.17+0.05;
  addG('stair',api.box(0.57,1.0,st.w*2+0.1).rotate(0,yaw,0).translate(x,top-0.5,z).vertexColor(()=>hs(s,si)>0.5?'#cfc4ad':'#c2b79f'));
  for(const sd of [-1,1]){const off=sd*(st.w+0.2);addG('wall',api.box(0.57,0.9,0.3).rotate(0,yaw,0).translate(x-P[3]*off,top+0.35,z+P[2]*off));}}}
}
const mats={road:{color:'#ffffff',roughness:0.95},pave:{color:'#ffffff',roughness:0.9},stair:{color:'#ffffff',roughness:0.9},plaza:{color:'#ffffff',roughness:0.85},wall:{color:'#cfc6b2',roughness:0.9},wallcap:{color:'#e5ddcc',roughness:0.8},bed:{color:'#ffffff',roughness:1},rail:{color:'#ffffff',roughness:0.4,metalness:0.7},pole:{color:'#2b2b2f',roughness:0.6,metalness:0.5},lamp:{color:'#ffd9a0',emissive:'#ffb050',emissiveIntensity:3,roughness:0.4}};
for(const k in G)api.add(G[k],mats[k]);
api.add(api.box(0.2,0.1,0.2).translate(-300,-11.95,-300),{color:'#444444'});
api.add(api.box(0.2,0.1,0.2).translate(300,-11.95,300),{color:'#444444'});
return api.build();

