const L=params.length,d=params.depth,f=params.foundation,r=()=>api.rng();
const gaps=[params.gap1,params.gap2,params.gap3,params.gap4].filter(g=>g>-900).map(g=>[g-params.gapW/2,g+params.gapW/2]);
if(params.plazaC>-900)gaps.push([params.plazaC-params.plazaW/2,params.plazaC+params.plazaW/2]);
const pal=['#e8c27a','#d98f7a','#efe3c8','#9fc0cf','#e6a95f','#c8d3a2','#f0d9d0','#d9a0a0','#f4efe0','#b9cfa8','#e7d27d','#c9a77c','#cbd9dc'];
const doors=['#3d5a45','#5a3a24','#2f4a6b','#7a2f2a'];
const trim={color:'#f6f1e6',roughness:0.8};
const dark={color:'#2b3640',roughness:0.3,metalness:0.1};
const lit={color:'#ffd08a',emissive:'#ffb860',emissiveIntensity:1.2,roughness:0.4};
const iron={color:'#25282c',roughness:0.6,metalness:0.4};
const roofs=['#b5532f','#a4452a','#c1623a'];
let x=0;
const hw=L/2;
let guard=0;
while(x<L&&guard++<400){
 const w=4.8+r()*2.4;
 let skip=false;
 for(const g of gaps){ if(x<g[1]&&x+w>g[0]){x=g[1];skip=true;break;} }
 if(skip)continue;
 if(x+w>L)break;
 const nfl=params.floorsMin+Math.floor(r()*(params.floorsMax-params.floorsMin+1));
 const h=3.5+(nfl-1)*3.05;
 const cx=x+w/2-hw;
 const col=pal[Math.floor(r()*pal.length)];
 const wm={color:col,roughness:0.92};
 api.add(api.box(w,h+f,d).translate(cx,(h-f)/2,0),wm);
 api.collider({kind:'box',halfExtents:[w/2,(h+f)/2,d/2],offset:[cx,(h-f)/2,0]});
 const zf=d/2;
 // ground floor
 const ds=r()<0.5?-1:1;
 api.add(api.box(1.15,2.35,0.16).translate(cx+ds*w*0.26,1.18,zf+0.02),trim);
 api.add(api.box(0.95,2.2,0.2).translate(cx+ds*w*0.26,1.1,zf+0.05),{color:doors[Math.floor(r()*4)],roughness:0.6});
 api.add(api.box(1.3,1.5,0.14).translate(cx-ds*w*0.24,1.7,zf+0.03),trim);
 api.add(api.box(1.1,1.3,0.18).translate(cx-ds*w*0.24,1.7,zf+0.05),r()<0.5?lit:dark);
 for(let i=1;i<nfl;i++){
  const yb=3.5+(i-1)*3.05;
  const nw=Math.max(2,Math.round(w/2.3));
  const bal=r()<0.35;
  for(let k=0;k<nw;k++){
   const wx=cx-w/2+w*(k+0.5)/nw;
   api.add(api.box(1.0,1.65,0.14).translate(wx,yb+1.45,zf+0.03),trim);
   api.add(api.box(0.8,1.45,0.18).translate(wx,yb+1.45,zf+0.05),r()<0.4?lit:dark);
  }
  if(bal){
   api.add(api.box(w*0.8,0.1,0.55).translate(cx,yb+0.55,zf+0.27),trim);
   api.add(api.box(w*0.8,0.05,0.05).translate(cx,yb+1.5,zf+0.5),iron);
   api.add(api.box(w*0.8,0.05,0.05).translate(cx,yb+1.0,zf+0.5),iron);
  }
 }
 api.add(api.box(w+0.12,0.3,0.45).translate(cx,h-0.1,zf+0.12),trim);
 const rise=0.9+r()*0.6,ang=Math.atan(rise/(d/2))*180/Math.PI,len=Math.sqrt((d/2+0.3)*(d/2+0.3)+rise*rise);
 const rm={color:roofs[Math.floor(r()*3)],roughness:0.85};
 api.add(api.box(w+0.1,0.14,len).rotate(ang,0,0).translate(cx,h+rise/2+0.05,d/4+0.1),rm);
 api.add(api.box(w+0.1,0.14,len).rotate(-ang,0,0).translate(cx,h+rise/2+0.05,-d/4-0.1),rm);
 api.add(api.extrude([[-d/2,0],[d/2,0],[0,rise]],w-0.05).rotate(0,90,0).translate(cx,h,0),wm);
 if(r()<0.35)api.add(api.box(0.55,1.4,0.55).translate(cx+(r()-0.5)*w*0.5,h+rise+0.3,-d/4),{color:'#d8cdb8',roughness:0.9});
 x+=w;
}
api.add(api.box(0.1,0.1,0.1).translate(-hw,-f+0.05,0),wm0());
api.add(api.box(0.1,0.1,0.1).translate(hw,-f+0.05,0),wm0());
function wm0(){return {color:'#8a8478',roughness:1};}
return api.build();

lisbon-row3.source:
const R=()=>api.rng();
const D=params.depth, hd=D/2, base=2.0;
const M={
 plaster:{finish:'plaster',preset:'concrete',color:'#ffffff',roughness:0.95},
 stone:{finish:'limestone',preset:'stone',color:'#ffffff',roughness:0.9},
 tile:{finish:'roof-tile',preset:'brick',color:'#ffffff',roughness:0.85},
 glass:{finish:'facade',preset:'glass',color:'#16222c',opacity:0.88,roughness:0.05},
 lit:{color:'#3a2a1a',emissive:'#ffb55e',emissiveIntensity:1.4,roughness:0.4},
 wood:{finish:'paint',preset:'wood',color:'#ffffff',roughness:0.7},
 iron:{finish:'paint',preset:'metal',color:'#ffffff',metalness:0.5,roughness:0.55},
 cloth:{preset:'fabric',color:'#ffffff',roughness:0.9},
 azul:{finish:'paint',preset:'stone',color:'#ffffff',roughness:0.22}
};
const pick=a=>a[Math.floor(R()*a.length)];
function B(k,w,h,d,x,y,z,c){const m=api.box(w,h,d).translate(x,y,z);m.vertexColor(()=>c);api.add(m,M[k]);return m;}
const plast=['#e9c98c','#dc9d70','#e8b9a3','#f1e3b8','#c9d6c8','#b9cdd8','#efe7d8','#d8a66e','#d3a3a2','#a9c3b2','#f3f0e8','#e2b57f','#e6c0a0'];
const trim=['#f6f1e6','#efe6d0','#ffffff'];
const shut=['#3f6b57','#8a3b2f','#2f5f8a','#5b4a3a','#2f4f46'];
const roofc=['#f2a077','#ef9468','#e8a27c','#f4b088','#e58f66'];
const tilec=['#9fbdd0','#a8c4a0','#ebd48e','#c8d8e0','#b8c8e0'];
const doorc=['#2f4f46','#6b2a24','#27405f','#3b2f26','#1f1f22'];
const iron='#27332c';
const fmin=params.floorsMin, fmax=Math.max(params.floorsMin,params.floorsMax);
const blocks=[];
for(const g of [params.gap1,params.gap2]) if(g>-900) blocks.push([g-88-params.gapW/2,g-88+params.gapW/2]);
if(params.plazaC>-900) blocks.push([params.plazaC-88-params.plazaW/2,params.plazaC-88+params.plazaW/2]);
blocks.sort((a,b)=>a[0]-b[0]);
const free=[];let cur=-88;
for(const b of blocks){ if(b[0]>cur+4) free.push([cur,Math.min(b[0],88)]); cur=Math.max(cur,b[1]); }
if(cur<88-4) free.push([cur,88]);
const houses=[];
for(const f of free){let x=f[0];while(x<f[1]-0.01){let w=5.2+R()*3.6;if(f[1]-x-w<4.6)w=f[1]-x;if(w>10.5)w=(f[1]-x)/2;houses.push([x,w]);x+=w;}}
for(const h of houses){
 const x0=h[0],w=h[1],xc=x0+w/2;
 const n=fmin+Math.floor(R()*(fmax-fmin+1));
 const gf=3.3,fh=3.1;
 const H=base+gf+(n-1)*fh+0.25;
 const pc=pick(plast), tc=pick(trim), azu=R()<0.18;
 const zf=hd;
 B('plaster',w,H,D,xc,H/2,0,pc);
 B('stone',w+0.02,1.0,0.07,xc,base+0.5,zf+0.03,'#d8d0bc');
 B('stone',w+0.1,0.22,D+0.7,xc,H-0.11,0,tc);
 if(azu){const ac=pick(tilec);B('azul',w-0.2,H-base-1.0-0.3,0.05,xc,(base+1.0+H-0.3)/2,zf+0.03,ac);
  for(let k=1;k<n;k++)B('stone',w-0.2,0.08,0.07,xc,base+gf+(k-1)*fh+0.02,zf+0.04,'#f2efe6');}
 const hz=hd+0.33, rise=hz*0.38;
 const rf=api.extrude([[-hz,0],[hz,0],[0,rise]],w-0.04).rotate(0,90,0).translate(xc,H,0);
 const rc=pick(roofc);rf.vertexColor(()=>rc);api.add(rf,M.tile);
 if(R()<0.6){B('plaster',0.5,1.3,0.5,xc+(R()-0.5)*(w-2),H+rise*0.5+0.6,-1.0,pc);}
 if(R()<0.5)B('iron',0.1,H-base-0.3,0.1,x0+w-0.18,(H+base)/2,zf+0.1,iron);
 const nw=Math.max(2,Math.floor(w/2.4)), sp=w/nw, door=Math.floor(R()*nw);
 const sh=R()<0.75?pick(shut):null;
 const lw=()=>R()<0.25?'lit':'glass';
 function win(cx,yb,ww,hh,balc){
  B('wood',ww+0.14,hh+0.14,0.06,cx,yb+hh/2,zf+0.03,'#f6f2ea');
  B(lw(),ww,hh,0.05,cx,yb+hh/2,zf+0.06,'#ffffff');
  B('wood',0.05,hh,0.06,cx,yb+hh/2,zf+0.09,'#f6f2ea');
  B('wood',ww,0.05,0.06,cx,yb+hh*0.62,zf+0.09,'#f6f2ea');
  B('stone',ww+0.3,0.07,0.2,cx,yb-0.04,zf+0.1,'#e8e2d2');
  if(sh){B('wood',0.5,hh,0.04,cx-ww/2-0.32,yb+hh/2,zf+0.03,sh);B('wood',0.5,hh,0.04,cx+ww/2+0.32,yb+hh/2,zf+0.03,sh);}
  if(balc){const bw=ww+0.5;B('stone',bw,0.12,0.6,cx,yb-0.1,zf+0.3,'#d8d0bc');B('iron',bw,0.04,0.04,cx,yb+0.95,zf+0.58,iron);B('iron',bw,0.04,0.04,cx,yb+0.25,zf+0.58,iron);
   for(let p=0;p<=6;p++)B('iron',0.025,0.95,0.025,cx-bw/2+0.02+p*(bw-0.04)/6,yb+0.5,zf+0.58,iron);
   B('iron',0.04,0.95,0.6,cx-bw/2+0.02,yb+0.5,zf+0.3,iron);B('iron',0.04,0.95,0.6,cx+bw/2-0.02,yb+0.5,zf+0.3,iron);}
 }
 for(let i=0;i<nw;i++){
  const cx=x0+(i+0.5)*sp;
  if(i===door){const dc=pick(doorc);B('stone',1.3,2.6,0.1,cx,base+0.1+1.3,zf+0.04,'#e4ddcb');B('wood',0.98,2.35,0.08,cx,base+0.1+1.175,zf+0.09,dc);B('glass',0.6,0.5,0.03,cx,base+2.1,zf+0.14,'#ffffff');B('stone',1.5,0.08,0.5,cx,base+0.06,zf+0.28,'#cfc8b6');
   if(R()<0.35){B('cloth',1.7,0.05,0.9,cx,base+2.9,zf+0.42,pick(['#b83a2e','#2f6f8f','#d79a2b','#3f6b57']));}}
  else win(cx,base+0.85,1.0,1.4,false);
  for(let k=1;k<n;k++){
   const yb=base+gf+(k-1)*fh;
   if(k===1&&(R()<0.45)) win(cx,yb+0.05,0.95,2.2,true); else win(cx,yb+0.9,1.0,1.45,false);
  }
 }
 api.collider({kind:'box',halfExtents:[w/2,H/2,hd],offset:[xc,H/2,0]});
}
return api.build();

lisbon-row4.source:
function FW(x){const c=Math.max(-135,Math.min(135,x));return -(0.0009*c*c+2.4*Math.sin(c/37+0.6)-2.4*Math.sin(0.6));}
function WW(z){const s=(a,b,v)=>{const t=Math.min(1,Math.max(0,(v-a)/(b-a)));return t*t*(3-2*t);};return s(-45,-18,z)*(1-s(96,114,z));}
function WD(x,z){return FW(x)*WW(z);}
const WX=params.wx,WZ=params.wz,WR=params.wr*Math.PI/180,WC=Math.cos(WR),WS=Math.sin(WR);
