const __add=(m,o)=>{const q=params.warp?m.warp(WARP):m;api.add(OX?q.translate(-OX,0,0):q,o);};
const __col=(c)=>{if(!params.warp&&!OX)return api.collider(c);const o=c.offset||[0,0,0];const p=params.warp?WARP(o[0],o[1],o[2]):o;return api.collider({...c,offset:[p[0]-OX,p[1],p[2]]});};
const x1 = params.halfLength, half = params.roadHalf, plaza = params.plaza;
const segs = plaza > 0 ? [[-x1, -plaza], [plaza, x1]] : [[-x1, x1]];
let road = null, rail = null;
const cell = 0.24;
for (const sg0 of segs) {
  const sg = clipR(sg0[0], sg0[1]);
  if (sg[1] - sg[0] < 0.05) continue;
  const w = sg[1] - sg[0], cx = (sg[0] + sg[1]) / 2, dxO = cx - (sg0[0] + sg0[1]) / 2;
  const wO = sg0[1] - sg0[0], cols = Math.max(1, Math.round(Math.max(4, Math.min(512, Math.round(wO / cell))) * w / wO));
  const rows = Math.max(4, Math.round(2 * half / cell));
  const hf = api.heightfield(cols, rows, w, 2 * half, (x, z) => 0.012 * api.noise2((x + dxO) * 4.1, z * 4.1))
    .vertexColor((x, y, z) => {
      const n = 0.5 + 0.5 * api.noise2((x + dxO) * 4.1 + 11, z * 4.1 + 3);
      const m = 0.5 + 0.5 * api.noise2((x + dxO) * 0.35, z * 0.9);
      const base = api.mix('#a59d90', '#d9d0bd', 0.35 + 0.3 * n);
      const warm = api.mix(base, '#c9a57a', 0.18 * m);
      const wear = Math.exp(-((z / half) * (z / half)) * 3.0) * 0.18;
      return api.mix(warm, '#d8cdb4', wear);
    })
    .translate(cx, 0.075, 0);
  road = road ? road.merge(hf) : hf;
  if (params.rails) {
    for (const s of [-1, 1]) {
      const r = api.box(w, 0.06, 0.07).translate(cx, 0.1, params.railZ + s * 0.72);
      rail = rail ? rail.merge(r) : r;
    }
  }
}
if (road) __add(road, { finish: 'cobble', preset: 'stone', color: '#ffffff', roughness: 0.9 });
if (rail) __add(rail, { preset: 'metal', color: '#8a8d92', roughness: 0.4, metalness: 0.8 });
// A tile is not recentred: its entity sits where the whole feature's recentred origin puts this tile's centre.
return api.build(TILED ? { recenter: false } : undefined);

lisbon-stairs.source:
const R=params.rise,Z=params.run,W=params.width;
const n=Math.round(R/0.2);
const sm={color:'#c7bfae',roughness:0.9};
const sm2={color:'#b3aa98',roughness:0.9};
for(let i=0;i<n;i++){
 const top=R*(1-(i+0.5)/n)+0.03;
 const h=top+0.3;
 api.add(api.box(W,h,Z/n+0.01).translate(0,(top-0.3)/2,(i+0.5)*Z/n),i%2?sm:sm2);
}
const len=Math.sqrt(Z*Z+R*R),ang=Math.atan(R/Z)*180/Math.PI;
for(const s of [-1,1])api.add(api.box(0.3,0.9,len).rotate(ang,0,0).translate(s*(W/2+0.2),R/2+0.35,Z/2),{color:'#e7dfcd',roughness:0.9});
api.collider({kind:'box',halfExtents:[0.01,0.01,0.01],offset:[0,0,0]});
return api.build();

lisbon-stairs3.source:
const W=params.width, Lz=params.length, rise=params.rise, n=36, r=rise/n, t=Lz/n, off=0.3;
const lime={finish:'limestone',preset:'stone',color:'#ffffff',roughness:0.88};
const pi={finish:'paint',preset:'metal',color:'#ffffff',metalness:0.5,roughness:0.5};
const pts=[[-Lz/2,0],[-Lz/2,off+0.5*r]];
for(let i=0;i<n;i++){const x0=-Lz/2+i*t, x1=x0+t, y=off+(i+0.5)*r; if(i>0)pts.push([x0,y]); pts.push([x1,y]);}
pts.push([Lz/2,off+rise]);pts.push([Lz/2,0]);
const st=api.extrude(pts,W).rotate(0,90,0);
st.vertexColor((x,y,z)=>api.mix('#d9d2c0','#ece6d6',0.5+0.5*api.noise2(x*3,z*3+y*2)));
api.add(st,lime);
const lineY=z=>off+rise*(Lz/2-z)/Lz;
const wt=0.28, wh=0.5;
for(const s of [-1,1]){
 const poly=[[-Lz/2,0],[-Lz/2,off+wh],[Lz/2,off+rise+wh],[Lz/2,0]];
 const w=api.extrude(poly,wt).rotate(0,90,0).translate(s*(W/2+wt/2),0,0);
 w.vertexColor(()=>'#e2dccb');api.add(w,lime);
 const ix=s*(W/2+wt/2), top=[];
 for(let k=0;k<=8;k++){const z=Lz/2-k*Lz/8;top.push([ix,lineY(z)+1.0,z]);}
 const rl=api.tube(top,0.025,6);rl.vertexColor(()=>'#25342b');api.add(rl,pi);
 for(let k=0;k<=8;k++){const z=Lz/2-k*Lz/8;const p=api.box(0.05,0.55,0.05).translate(ix,lineY(z)+wh+0.27,z);p.vertexColor(()=>'#25342b');api.add(p,pi);}
}
// Walked on a smooth ramp along the nosings (the drawn steps are narrower than the walker's step), as games do with stairs.
{const L=Math.hypot(Lz,rise), a=Math.atan2(rise,Lz)*180/Math.PI;
 api.collider({kind:'box',halfExtents:[W/2,0.1,L/2],offset:[0,off+rise/2-0.12,0],rotation:[a,0,0]});
 api.collider({kind:'box',halfExtents:[W/2,off/2,0.6],offset:[0,off/2,Lz/2+0.5]});}
return api.build();

lisbon-street.source:
const L=params.length,W=params.width;
const m=api.plane(L,W,Math.round(L/0.25),Math.round(W/0.25));
m.vertexColor((x,y,z)=>{
 const i=Math.floor(x/0.5),j=Math.floor(z/0.5);
 const n=api.noise2(i*7.3,j*5.1);
 const az=Math.abs(z);
 if(az>W/2-0.9){
  const dk=((i+Math.floor(j/2))%5===0);
  return dk?'#6e6a66':api.mix('#d9d2c2','#c8bfae',0.5+0.5*n);
 }
 if(az>W/2-1.05)return '#9a948a';
 return api.mix('#8a857e','#a8a298',0.5+0.5*n);
});
api.add(m,{roughness:0.95,metalness:0});
if(params.rails){
 const rz=params.railZ;
 for(const s of [-0.72,0.72])api.add(api.box(L,0.08,0.07).translate(0,0.06,rz+s),{color:'#7a7e84',roughness:0.4,metalness:0.8});
 for(let x=-L/2+1;x<L/2;x+=1.3)api.add(api.box(0.2,0.04,1.9).translate(x,0.03,rz),{color:'#4a3b30',roughness:0.9});
}
return api.build();

lisbon-street3.source:
function FW(x){const c=Math.max(-135,Math.min(135,x));return -(0.0009*c*c+2.4*Math.sin(c/37+0.6)-2.4*Math.sin(0.6));}
function WW(z){const s=(a,b,v)=>{const t=Math.min(1,Math.max(0,(v-a)/(b-a)));return t*t*(3-2*t);};return s(-45,-18,z)*(1-s(96,114,z));}
function WD(x,z){return FW(x)*WW(z);}
const WX=params.wx,WZ=params.wz,WR=params.wr*Math.PI/180,WC=Math.cos(WR),WS=Math.sin(WR);
function WARP(x,y,z){const gx=WX+WC*x+WS*z,gz=WZ-WS*x+WC*z,nz=gz+WD(gx,gz);return [WC*(gx-WX)-WS*(nz-WZ),y,WS*(gx-WX)+WC*(nz-WZ)];}
const TILED=params.tile1>params.tile0,OX=TILED?(params.tile0+params.tile1)/2:0,T0=TILED?params.tile0:-1e9,T1=TILED?params.tile1:1e9;
const inT=(x)=>x>=T0&&x<T1;const clipR=(a,b)=>[Math.max(a,T0),Math.min(b,T1)];
const __add=(m,o)=>{const q=params.warp?m.warp(WARP):m;api.add(OX?q.translate(-OX,0,0):q,o);};
const __col=(c)=>{if(!params.warp&&!OX)return api.collider(c);const o=c.offset||[0,0,0];const p=params.warp?WARP(o[0],o[1],o[2]):o;return api.collider({...c,offset:[p[0]-OX,p[1],p[2]]});};
const LF=params.length, LR=clipR(-LF/2,LF/2), L=Math.max(0.2,LR[1]-LR[0]), CX=(LR[0]+LR[1])/2, rh=2.5, sw=3.78, cobble=params.surface==='cobble';
const cell=0.2, cols=Math.max(1,Math.round(Math.min(512,Math.round(LF/cell))*L/LF)), rows=Math.round(2*rh/cell);
const road=api.heightfield(cols,rows,L,2*rh,(x,z)=>0.04+(cobble?0.012*api.noise2((x+CX)*8,z*8):0.004*api.noise2((x+CX)*3,z*3)));
road.translate(CX,0,0);
road.vertexColor((x,y,z)=>{
 const n=api.noise2((x+CX)*5.1,z*5.1)*0.5+api.noise2((x+CX)*0.7,z*0.7)*0.5;
 if(cobble){const t=0.5+0.5*n;return api.mix('#8a847a','#c2baa8',t);}
 let c=api.mix('#4a4b50','#62636a',0.5+0.5*n);
 if(params.rails&&Math.abs(z-params.railZ)<0.75)c=api.mix(c,'#6e6a62',0.5);
 return c;});
__add(road,cobble?{finish:'cobble',preset:'stone',color:'#ffffff',roughness:0.92}:{finish:'asphalt',preset:'concrete',color:'#ffffff',roughness:0.88});
const slab=api.box(L,0.04,2*rh).translate(CX,0.02,0);slab.vertexColor(()=>'#8a857b');__add(slab,{finish:'asphalt',preset:'concrete',color:'#ffffff',roughness:0.95});
const lime={finish:'limestone',preset:'stone',color:'#ffffff',roughness:0.8};
for(const s of [-1,1]){
 const pw=sw-rh, zc=s*(rh+pw/2);
 const pc=Math.max(1,Math.round(Math.min(512,Math.round(LF/0.12))*L/LF)), pr=Math.round(pw/0.12);
 const pv=api.heightfield(pc,pr,L,pw,(x,z)=>0.1+0.003*api.noise2((x+CX)*10,z*10));
 pv.vertexColor((x,y,z)=>{const w=Math.sin((x+CX)*1.3+Math.sin(z*2.4+(x+CX)*0.15)*1.2);const edge=Math.abs(z)>pw/2-0.22;
  if(edge)return '#3a3a3d';return w>0.15?'#f0eadb':(w<-0.35?'#ddd6c4':'#3c3c40');});
 pv.translate(CX,0,zc);__add(pv,lime);
 const base=api.box(L,0.1,pw).translate(CX,0.05,zc);base.vertexColor(()=>'#cfc8b6');__add(base,lime);
 const kerb=api.box(L,0.12,0.18).translate(CX,0.06,s*(rh+0.09));kerb.vertexColor(()=>'#a8a49c');__add(kerb,{finish:'stone',preset:'stone',color:'#ffffff',roughness:0.85});
}
const bm={finish:'brushed-metal',preset:'metal',color:'#ffffff',metalness:0.8,roughness:0.4};
if(params.rails){
 for(const d of [-0.45,0.45]){const r=api.box(L,0.07,0.06).translate(CX,0.075,params.railZ+d);r.vertexColor(()=>'#8a8782');__add(r,bm);}
 const ng=Math.round(LF/1.6);
 for(let i=0;i<ng;i++){if(!inT(-LF/2+0.8+i*1.6))continue;const sl=api.box(0.16,0.04,1.5).translate(-LF/2+0.8+i*1.6,0.06,params.railZ);sl.vertexColor(()=>'#5a4e40');__add(sl,{finish:'oak',preset:'wood',color:'#ffffff',roughness:0.9});}
}
for(let i=0;i<6;i++){const x=-LF/2+12+i*(LF-24)/5+api.rng()*4, z=(api.rng()-0.5)*1.4+(params.rails?1.2:0);if(!inT(x))continue;
 const m=api.cylinder(0.36,0.36,0.012,16).translate(x,0.058,z);m.vertexColor(()=>'#5a5a5c');__add(m,bm);}
// A tile is not recentred: its entity sits where the whole feature's recentred origin puts this tile's centre.
return api.build(TILED ? { recenter: false } : undefined);

lisbon-terrain3.source:
const ss=(a,b,x)=>{let t=Math.min(1,Math.max(0,(x-a)/(b-a)));return t*t*(3-2*t);};
const lv=[39.6,33.1,26.6,20.1,13.6,7.1,0.6],zb=[5,26,47,68,89,110];
const st=[[-34,50],[-60,30],[-28,62],[-74,44],[-46,70],[-64,24]];
function H0(x,z){
 const ax=Math.abs(x);
 let b=lv[0];
 for(let i=0;i<6;i++)b+=(lv[i+1]-lv[i])*ss(zb[i]-1,zb[i]+1,z);
 if(ax<100&&z>-10&&z<140){
  for(let i=0;i<6;i++){
   if(z<zb[i]-7.5||z>zb[i]+7.5)continue;
   for(const sx of st[i]){
    const w=1-ss(1.6,2.6,Math.abs(x-sx));
    if(w>0){const t=Math.min(1,Math.max(0,(z-(zb[i]-3.75))/7.5));const ry=lv[i]+(lv[i+1]-lv[i])*t-0.2*Math.min(1,6*Math.min(t,1-t));b=b*(1-w)+ry*w;}
   }
  }
 }
 let land=b;
 land+=30*ss(0,1,(-75-z)/130);
 const hr=55*ss(0,1,(ax-115)/150)+0.06*Math.max(0,ax-265);
 const nw=ss(0,1,(ax-120)/60);
 land+=hr;
 if(z>134)land+=40*ss(0,1,(z-300)/130);
 if(nw>0)land+=nw*(7*api.fbm2(x*0.012,z*0.012,3)+2*api.fbm2(x*0.05,z*0.05,2));
 if(z>134){
  const m=ss(0,1,(175-ax)/12)*ss(0,1,(320-z)/20)*ss(0,1,(z-134)/3);
  return land*(1-m)-3*m;
 }
 return land;
}
// Mediterranean hillside colour: dry grass and olive scrub in patches, red soil on paths, limestone where it is steep.
function C(x,z,y){
 const e=1.5,sx=(H(x+e,z)-H(x-e,z))/(2*e),sz=(H(x,z+e)-H(x,z-e))/(2*e),sl=Math.sqrt(sx*sx+sz*sz);
 const n1=api.fbm2(x*0.018,z*0.018,3),n2=api.noise2(x*0.09,z*0.09),n3=api.noise2(x*0.31+7,z*0.31-3);
 let c=api.mix('#5f7a35','#8f8c4e',Math.min(1,Math.max(0,0.5+0.9*n1)));
 c=api.mix(c,'#3f5a2a',Math.min(1,Math.max(0,0.7*n2+0.3)));
 c=api.mix(c,'#9b6b45',Math.min(1,Math.max(0,(n3-0.55)*2.2))*0.6);
 const rk=Math.min(1,Math.max(0,(sl-1.0)*1.5))*(0.6+0.4*Math.max(0,n2));
 if(rk>0)c=api.mix(c,api.mix('#a49a86','#c8bda4',0.5+0.5*n2),rk);

 // Far slopes read as forest canopy (trees out there are past the instance budget): dark mottled greens with lit crowns.
 const far=Math.min(1,Math.max(0,(Math.hypot(x/1.3,z-30)-170)/120))*(1-rk*0.4);
 if(far>0){const t=api.noise2(x*0.06+3,z*0.06-5),u=api.noise2(x*0.17,z*0.17);c=api.mix(c,api.mix(api.mix('#2c3f22','#4a5f2c',0.5+0.5*t),'#6b7436',Math.max(0,u)*0.6),far*0.9);}
 return c;
}
function FW(x){const c=Math.max(-135,Math.min(135,x));return -(0.0009*c*c+2.4*Math.sin(c/37+0.6)-2.4*Math.sin(0.6));}
function WW(z){const s=(a,b,v)=>{const t=Math.min(1,Math.max(0,(v-a)/(b-a)));return t*t*(3-2*t);};return s(-45,-18,z)*(1-s(96,114,z));}
function WD(x,z){return FW(x)*WW(z);}
function H(x,z){let z0=z;for(let i=0;i<4;i++)z0=z-WD(x,z0);return H0(x,z0);}
const P=params.part;
let m;
if(P===0){
 const zc=37.5;
 m=api.plane(300,225,200,150).displace((x,y,z)=>Math.max(-3,H(x,z+zc)));
 m.vertexColor((x,y,z)=>{
  const wz=z+zc;
  if(y<-1.5)return '#0d171a';
  if(y<0.4&&wz>120)return '#c9bda2';
  if(Math.abs(x)<112&&wz<135&&wz>-10)return '#b0a086';
  return C(x,wz,y);
 });
}else{
 const zc=200;
 m=api.plane(1600,1100,160,110).displace((x,y,z)=>{
  const wz=z+zc;
  const h=H(x,wz);
  const f=ss(0,1,(150-Math.abs(x))/20)*ss(0,1,(wz+75)/20)*ss(0,1,(150-wz)/20);
  return Math.max(-3.2,h-0.6-3*f);
 });
 m.vertexColor((x,y,z)=>{
  if(y<-1.5)return '#0d171a';
  return C(x,z+zc,y);
 });
}
api.add(m,{roughness:0.95,metalness:0});
api.autoColliders("trimesh");
return api.build();

lisbon-tram.source:
