 for(let k=-3;k<=3;k++)api.add(api.box(0.04,0.8,1.0).translate(sd*(Wd/2+0.01),2.25,k*1.18),G);
 api.add(api.box(0.04,0.55,1.0).translate(sd*(Wd/2+0.01),1.0,-0.0),G);
 for(const z of [-3.2,3.2]){api.add(api.cylinder(0.42,0.42,0.12,14).rotate(0,0,90).translate(sd*0.95,0.42,z),I);api.add(api.cylinder(0.42,0.42,0.12,14).rotate(0,0,90).translate(sd*0.95,0.42,z*0.55),I);}
}
