api.add(api.box(1.6,0.08,0.08).translate(0,3.35,0.4),I);
api.add(api.box(0.06,0.5,0.06).translate(0,3.1,0.4),I);
api.add(api.box(0.06,0.06,1.6).translate(0,3.55,0.4),I);
for(const z of [-1,1]){api.add(api.box(Wd-0.2,0.28,0.2).translate(0,0.55,z*(L/2+0.05)),I);
 api.add(api.box(0.3,0.25,0.06).translate(0.7,1.5,z*(L/2+0.02)),{color:'#fff7d0',emissive:'#fff2b0',emissiveIntensity:1.2});
 api.add(api.box(0.3,0.25,0.06).translate(-0.7,1.5,z*(L/2+0.02)),{color:'#fff7d0',emissive:'#fff2b0',emissiveIntensity:1.2});}
api.collider({kind:'box',halfExtents:[1.2,1.8,4.5],offset:[0,1.8,0]});
return api.build();

lisbon-tram3.source:
const L=params.length, Wd=2.3;
const P=(m,mat,c)=>{m.vertexColor(()=>c);api.add(m,mat);};
const paint={finish:'paint',preset:'plastic',color:'#ffffff',roughness:0.35,metalness:0.2};
const met={finish:'brushed-metal',preset:'metal',color:'#ffffff',metalness:0.7,roughness:0.5};
const gl={preset:'glass',color:'#1b2a36',opacity:0.85,roughness:0.05};
const em={color:'#fff0c0',emissive:'#fff0c0',emissiveIntensity:3,roughness:0.3};
P(api.box(L,0.55,Wd).translate(0,0.85,0),paint,'#e3ae1f');
P(api.box(L-0.1,0.18,Wd+0.02).translate(0,1.2,0),paint,'#f2ead2');
P(api.box(L,0.12,Wd).translate(0,2.5,0),paint,'#f2ead2');
const np=8, pitch=(L-0.6)/np;
for(let i=0;i<=np;i++)P(api.box(0.12,1.15,Wd+0.02).translate(-L/2+0.3+i*pitch,1.9,0),paint,'#e3ae1f');
for(let i=0;i<np;i++)for(const s of [-1,1])P(api.box(pitch-0.14,0.95,0.05).translate(-L/2+0.3+(i+0.5)*pitch,1.95,s*(Wd/2-0.02)),gl,'#ffffff');
P(api.box(L,0.95,Wd-0.1).translate(0,1.95,0),paint,'#2a2218');
P(api.box(L-0.4,0.16,Wd-0.2).translate(0,2.62,0),paint,'#3a3d40');
P(api.box(L-0.2,0.08,0.6).translate(0,2.75,0),paint,'#d9d4c4');
for(const s of [-1,1]){
 P(api.box(0.1,1.1,1.5).translate(s*(L/2+0.01),1.95,0),gl,'#ffffff');
 for(const z of [-0.8,0.8])P(api.sphere(0.12,2).translate(s*(L/2+0.06),0.85,z),em,'#ffffff');
 P(api.box(0.12,0.12,0.5).translate(s*(L/2+0.02),2.45,0),em,'#ffe9a0');
 P(api.box(0.25,0.15,Wd-0.2).translate(s*(L/2+0.1),0.45,0),met,'#4a4a4c');
}
const pg=api.tube([[-0.9,2.8,0],[-0.1,3.5,0],[0.7,2.8,0]],0.03,6);P(pg,met,'#2e2e30');
P(api.box(0.08,0.04,1.4).translate(-0.1,3.52,0),met,'#2e2e30');
for(const bx of [-L/2+1.7,L/2-1.7]){
 P(api.box(2.0,0.2,1.1).translate(bx,0.42,0),met,'#303032');
 for(const dx of [-0.55,0.55])for(const z of [-0.45,0.45]){const w=api.cylinder(0.3,0.3,0.1,16).rotate(90,0,0).translate(bx+dx,0.3,z);P(w,met,'#3a3a3c');}
}
P(api.box(L-0.4,0.3,Wd-0.1).translate(0,0.55,0),paint,'#4a4036');
return api.build();

red-bridge2.source:
const red={color:params.color,roughness:0.5,metalness:0.3},dk={color:'#4a4a4e',roughness:0.9},wh={color:'#e8e2d4',roughness:0.7};
const T=22,DT=8;
// deck
api.add(api.box(10.4,0.9,107).translate(0,DT-0.45,0),dk);
api.add(api.box(0.8,1.4,107).translate(-5.6,DT-0.5,0),red);api.add(api.box(0.8,1.4,107).translate(5.6,DT-0.5,0),red);
api.add(api.box(0.12,0.01,107).translate(0,DT+0.01,0),wh);
for(const sx of [-1,1])api.add(api.box(0.1,1.0,107).translate(sx*5.3,DT+0.5,0),wh);
// ramp
const rise=0.57,rl=12.1,rp=-Math.atan2(rise,12)*180/Math.PI;
api.add(api.box(10.4,0.6,rl).rotate(rp,0,0).translate(0,DT-rise/2-0.3,-53.5-6),dk);
// piers + towers
for(const tz of [-T,T]){
 for(const sx of [-1,1]){api.add(api.box(1.3,DT+34,2.2).translate(sx*5.9,(DT+34)/2,tz),red);}
 api.add(api.box(11.2,1.3,1.6).translate(0,DT+13,tz),red);api.add(api.box(11.2,1.3,1.6).translate(0,DT+25,tz),red);api.add(api.box(12,1.8,2.0).translate(0,DT+33.5,tz),red);
 api.add(api.box(11.5,DT,3.4).translate(0,DT/2-0.0,tz),{color:'#8a8478',roughness:0.95});
}
// cables
const cy=z=>{const a=Math.abs(z);return a<=T?DT+4+30*(z/T)*(z/T):DT+34-(a-T)/(53.5-T)*(34-2.5);};
const pts=[];for(let z=-53.5;z<=53.6;z+=(Math.abs(z)<T?2.75:3.1)){pts.push([0,cy(z),z]);}
for(const sx of [-1,1]){api.add(api.tube(pts.map(p=>[sx*5.9,p[1],p[2]]),0.16,6),red);
 for(let z=-19.8;z<=19.9;z+=2.2){const y=cy(z);api.add(api.box(0.07,y-DT-0.2,0.07).translate(sx*5.9,(y+DT+0.2)/2,z),{color:'#b8b2a4',roughness:0.5,metalness:0.6});}
 for(let z=-50;z<=50;z+=5.5){if(Math.abs(z)>T+1){const y=cy(z);api.add(api.box(0.06,y-DT-0.2,0.06).translate(sx*5.9,(y+DT+0.2)/2,z),{color:'#b8b2a4',roughness:0.5,metalness:0.6});}}}
api.collider({kind:'box',halfExtents:[5.2,0.45,53.5],offset:[0,DT-0.45,0]});
api.collider({kind:'box',halfExtents:[5.2,0.3,6.05],offset:[0,DT-rise/2-0.3,-59.5],rotation:[rp,0,0]});
for(const tz of [-T,T])for(const sx of [-1,1])api.collider({kind:'box',halfExtents:[0.65,(DT+34)/2,1.1],offset:[sx*5.9,(DT+34)/2,tz]});
api.add(api.box(0.2,0.1,0.2).translate(0,0.05,-66),{color:'#444444'});api.add(api.box(0.2,0.1,0.2).translate(0,0.05,66),{color:'#444444'});
return api.build();

red-bridge3.source:
const red={color:params.color,roughness:0.55,metalness:0.3};
const grey={color:'#7d8186',roughness:0.8};
const dk={color:'#3a3d42',roughness:0.9};
const E=186,T=90,DY=28,TOP=68,Wd=11;
api.add(api.box(2*E,0.8,Wd).translate(0,DY-0.4,0),dk);
api.collider({kind:'box',halfExtents:[E,0.4,Wd/2],offset:[0,DY-0.4,0]});
for(const s of [-1,1]){
 api.add(api.box(2*E,2.4,0.4).translate(0,DY-1.2,s*(Wd/2-0.2)),red);
 api.add(api.box(2*E,0.15,0.15).translate(0,DY+1.1,s*(Wd/2-0.1)),grey);
 api.add(api.box(2*E,0.15,0.15).translate(0,DY+0.55,s*(Wd/2-0.1)),grey);
}
for(let x=-E+3;x<E;x+=6){ for(const s of [-1,1])api.add(api.box(0.2,2.2,0.2).translate(x,DY-1.2,s*(Wd/2-0.2)).rotate(0,0,0),red); }
for(const tx of [-T,T]){
 for(const s of [-1,1]){
  api.add(api.box(3.2,TOP,2.4).translate(tx,TOP/2,s*5.6),red);
  api.collider({kind:'box',halfExtents:[1.6,TOP/2,1.2],offset:[tx,TOP/2,s*5.6]});
 }
 for(const y of [DY+14,DY+28,TOP-1.5])api.add(api.box(2.6,2.2,13).translate(tx,y,0),red);
}
function cab(s){
 const pts=[];
 for(let x=-E;x<=E;x+=6){
  let y;const ax=Math.abs(x);
  if(ax<=T){const u=x/T;y=DY+4+(TOP-1-(DY+4))*u*u;}
  else{const u=(ax-T)/(E-T);y=(TOP-1)-(TOP-1-(DY+2))*Math.pow(u,1.7);}
  pts.push([x,y,s*5.6]);
 }
 api.add(api.tube(pts,0.45,6),red);
 for(let x=-E+6;x<E;x+=6){
  const p=pts[Math.round((x+E)/6)];
  const h=p[1]-(DY+0.3);
  if(h>1)api.add(api.box(0.12,h,0.12).translate(x,DY+0.3+h/2,s*5.6),grey);
 }
}
cab(-1);cab(1);
return api.build();

red-bridge4.source:
const L = params.length, TH = params.towerH, col = params.color;
const T = L * 0.28, deckY = TH * 0.26, W = 14;
const red = [], dark = [], grey = [], cab = [];
const R = (m, c, list) => list.push(m.vertexColor(() => c));
const dk = '#8f2018', cc = '#d24a3a';
// towers
for (const sx of [-1, 1]) {
  for (const sz of [-1, 1]) {
    R(api.roundedBox(3.2, TH, 3.2, 0.3, 2).translate(sx * T, TH / 2, sz * (W / 2 - 0.5)), col, red);
    R(api.box(4.6, 3, 4.6).translate(sx * T, 1.5, sz * (W / 2 - 0.5)), '#9a9488', grey);
  }
  const ys = [deckY + 6, TH * 0.55, TH * 0.78, TH - 1.5];
  for (const y of ys) R(api.roundedBox(2.4, 2.6, W - 0.8, 0.3, 2).translate(sx * T, y, 0), col, red);
  // diagonal braces
  for (let i = 0; i < ys.length - 1; i++) {
    const y0 = ys[i], y1 = ys[i + 1], dy = y1 - y0, dz = W - 3.5, len = Math.sqrt(dy * dy + dz * dz);
    const ang = Math.atan2(dz, dy) * 180 / Math.PI;
    R(api.box(1.0, len, 1.0).rotate(-ang, 0, 0).translate(sx * T, (y0 + y1) / 2, 0), dk, red);
    R(api.box(1.0, len, 1.0).rotate(ang, 0, 0).translate(sx * T, (y0 + y1) / 2, 0), dk, red);
  }
  R(api.box(3.6, 1.2, 3.6).translate(sx * T, TH + 0.6, -(W / 2 - 0.5)), dk, red);
  R(api.box(3.6, 1.2, 3.6).translate(sx * T, TH + 0.6, W / 2 - 0.5), dk, red);
}
// deck truss
R(api.box(L, 2.2, W).translate(0, deckY - 1.1, 0), '#a8392e', red);
R(api.box(L, 0.4, W - 1).translate(0, deckY + 0.2, 0), '#3a3a3e', dark);
R(api.box(L, 0.2, 0.3).translate(0, deckY + 0.5, 0), '#e8e0c8', grey);
for (const sz of [-1, 1]) {
  R(api.box(L, 0.15, 0.15).translate(0, deckY + 1.5, sz * (W / 2 - 0.2)), '#b9a89a', grey);
  R(api.box(L, 0.4, 0.4).translate(0, deckY + 0.5, sz * (W / 2 - 0.2)), '#b9a89a', grey);
}
const nTruss = Math.floor(L / 6);
for (let i = 0; i <= nTruss; i++) {
  const x = -L / 2 + (L * i) / nTruss;
  for (const sz of [-1, 1]) R(api.box(0.25, 2.2, 0.25).translate(x, deckY - 1.1, sz * (W / 2 + 0.05)), dk, red);
}
// piers
for (const x of [-L / 2, L / 2, -L * 0.42, L * 0.42, -L * 0.15, L * 0.15]) {
  R(api.box(5, deckY - 2.2, W - 3).translate(x, (deckY - 2.2) / 2, 0), '#9a9488', grey);
}
// cables and hangers
const cableY = (x) => {
  const ax = Math.abs(x);
  if (ax <= T) return deckY + 7 + (TH - deckY - 6) * (x / T) * (x / T);
  return TH + 0.2 - ((ax - T) / (L / 2 - T)) * (TH - deckY - 3);
};
for (const sz of [-1, 1]) {
  const pts = [];
  const n = 70;
  for (let i = 0; i <= n; i++) {
    const x = -L / 2 + (L * i) / n;
    pts.push([x, cableY(x), sz * (W / 2 - 0.5)]);
  }
  R(api.tube(pts, 0.45, 6), cc, cab);
  for (let x = -L / 2 + 8; x < L / 2 - 4; x += 8) {
    if (Math.abs(Math.abs(x) - T) < 2) continue;
    const y = cableY(x), h = y - deckY - 0.4;
    if (h > 1) R(api.box(0.12, h, 0.12).translate(x, deckY + 0.4 + h / 2, sz * (W / 2 - 0.5)), '#c8bfae', grey);
  }
}
const mats = { red: { color: '#ffffff', roughness: 0.55, metalness: 0.35 }, dark: { color: '#ffffff', roughness: 0.9, metalness: 0 }, grey: { color: '#ffffff', roughness: 0.85, metalness: 0.05 }, cab: { color: '#ffffff', roughness: 0.5, metalness: 0.4 } };
const groups = { red, dark, grey, cab };
for (const k of Object.keys(groups)) {
  let a = groups[k];
  while (a.length > 1) {
    const nx = [];
    for (let i = 0; i < a.length; i += 2) { if (i + 1 < a.length) a[i].merge(a[i + 1]); nx.push(a[i]); }
    a = nx;
  }
  if (a.length) api.add(a[0], mats[k]);
}
api.collider({ kind: 'box', halfExtents: [L / 2, 1.2, W / 2], offset: [0, deckY - 1, 0] });
return api.build();

red-bridge5.source:
var L = params.length, H = params.towerH, col = params.color;
var paint = {color: col, roughness: 0.55, metalness: 0.35};
var paintDark = {color: api.mix(col, '#3a1010', 0.3), roughness: 0.6, metalness: 0.35};
var cableM = {color: api.mix(col, '#401410', 0.35), roughness: 0.5, metalness: 0.4};
var road = {color: '#2b2b2f', roughness: 0.95};
var conc = {color: '#b8b2a6', roughness: 0.95};
var white = {color: '#e8e4d8', roughness: 0.8};
var lampM = {color: '#ffd9a0', emissive: '#ffb860', emissiveIntensity: 3};
var W = 22;
var deckY = Math.max(10, H * 0.22);
var xt = L * 0.28;
var zc = W / 2 + 1.2;
var half = L / 2;
api.add(api.box(L, 1.2, W).translate(0, deckY, 0), road);
for (var s = -1; s <= 1; s += 2) {
  api.add(api.box(L, 0.5, 0.5).translate(0, deckY + 0.85, s * (W / 2 - 0.4)), conc);
  api.add(api.box(L, 0.12, 0.15).translate(0, deckY + 1.9, s * (W / 2 - 0.3)), paint);
  api.add(api.box(L, 0.12, 0.15).translate(0, deckY + 1.4, s * (W / 2 - 0.3)), paint);
  api.add(api.box(L, 0.8, 0.9).translate(0, deckY, s * (W / 2)), paint);
  api.add(api.box(L, 0.8, 0.9).translate(0, deckY - 5, s * (W / 2)), paint);
}
var posts = null;
for (var xp = -half + 0.75; xp < half; xp += 1.5) {
  for (var sp = -1; sp <= 1; sp += 2) {
    var pp = api.box(0.08, 1.1, 0.08).translate(xp, deckY + 1.6, sp * (W / 2 - 0.3));
    posts = posts ? posts.merge(pp) : pp;
  }
}
api.add(posts, paint);
for (var x = -half + 6; x < half - 3; x += 12) {
  api.add(api.box(5, 0.05, 0.25).translate(x, deckY + 0.63, 0), white);
}
var idx = 0;
for (var x2 = -half + 1.5; x2 < half; x2 += 3) {
  idx++;
  api.add(api.box(0.6, 0.7, W).translate(x2, deckY - 0.9, 0), paintDark);
  for (var s2 = -1; s2 <= 1; s2 += 2) {
    api.add(api.box(0.4, 5, 0.5).translate(x2 - 1.5, deckY - 2.5, s2 * (W / 2)), paint);
    var ang = Math.atan2(5, 3) * 180 / Math.PI;
    var len = Math.sqrt(9 + 25);
    var sg = (idx % 2 === 0) ? 1 : -1;
    api.add(api.box(len, 0.35, 0.4).rotate(0, 0, sg * ang).translate(x2, deckY - 2.5, s2 * (W / 2)), paint);
  }
}
for (var x3 = -half + 12; x3 < half - 6; x3 += 24) {
  for (var s3 = -1; s3 <= 1; s3 += 2) {
    api.add(api.cylinder(0.08, 0.1, 5, 6).translate(x3, deckY + 3.1, s3 * (W / 2 - 0.3)), paintDark);
    api.add(api.sphere(0.28, 1).translate(x3, deckY + 5.8, s3 * (W / 2 - 0.3)), lampM);
  }
}
for (var t = -1; t <= 1; t += 2) {
  var tx = t * xt;
  api.add(api.roundedBox(10, deckY - 4, W + 10, 0.5).translate(tx, (deckY - 4) / 2, 0), conc);
  api.add(api.roundedBox(10, deckY + 1, W + 4, 0.6).translate(t * (half - 5), (deckY + 1) / 2, 0), conc);
  for (var s4 = -1; s4 <= 1; s4 += 2) {
    var zz = s4 * zc;
    api.add(api.roundedBox(2.8, H, 2.6, 0.35).translate(tx, H / 2, zz), paint);
    for (var py = 3; py < H - 3; py += 4.5) for (var pf = -1; pf <= 1; pf += 2) {
      api.add(api.roundedBox(2.0, 3.4, 0.12, 0.05).translate(tx, py + 1.7, zz + pf * 1.33), paintDark);
      api.add(api.roundedBox(0.12, 3.4, 1.8, 0.05).translate(tx + pf * 1.43, py + 1.7, zz), paintDark);
    }
    api.add(api.roundedBox(3.4, 1.4, 3.2, 0.3).translate(tx, H + 0.5, zz), paintDark);
    api.add(api.roundedBox(3.4, 1.8, 3.2, 0.3).translate(tx, deckY + 1, zz), paintDark);
    api.collider({kind: 'box', halfExtents: [1.4, H / 2, 1.3], offset: [tx, H / 2, zz]});
  }
  var nb = 4;
  for (var b = 0; b < nb; b++) {
    var by = deckY + 10 + b * ((H - deckY - 14) / (nb - 1));
    api.add(api.box(2.2, 2.2, 2 * zc).translate(tx, by, 0), paint);
    if (b < nb - 1) {
      var by2 = by + (H - deckY - 14) / (nb - 1);
      var dy = by2 - by, dz = 2 * zc;
      var dl = Math.sqrt(dy * dy + dz * dz);
      var da = Math.atan2(dy, dz) * 180 / Math.PI;
      api.add(api.box(1.0, 0.7, dl).rotate(da, 0, 0).translate(tx, by + dy / 2, 0), paintDark);
      api.add(api.box(1.0, 0.7, dl).rotate(-da, 0, 0).translate(tx, by + dy / 2, 0), paintDark);
    }
  }
  api.add(api.box(2.6, 2.6, 2 * zc).translate(tx, H - 1, 0), paint);
}
function cy(xv) {
  var ax = Math.abs(xv);
  if (ax <= xt) {
    var u = xv / xt;
    return deckY + 6 + (H - deckY - 6) * u * u;
  }
  var tt = (ax - xt) / (half - xt);
  return H + (deckY + 6 - H) * tt - 5 * 4 * tt * (1 - tt);
}
for (var s5 = -1; s5 <= 1; s5 += 2) {
  var path = [];
  for (var xc = -half; xc <= half + 0.01; xc += 4) {
    path.push([xc, cy(xc) + 0.6, s5 * zc]);
  }
  api.add(api.tube(path, 0.5, 6), cableM);
  for (var xh = -half + 4; xh < half - 2; xh += 4) {
    if (Math.abs(Math.abs(xh) - xt) < 2) continue;
    var top = cy(xh);
    var hl = top - (deckY + 0.6);
    if (hl < 0.5) continue;
    api.add(api.box(0.12, hl, 0.12).translate(xh, deckY + 0.6 + hl / 2, s5 * zc - 0.25), cableM);
    api.add(api.box(0.12, hl, 0.12).translate(xh, deckY + 0.6 + hl / 2, s5 * zc + 0.25), cableM);
    api.add(api.box(0.35, 0.35, 0.35).translate(xh, top, s5 * zc), paintDark);
  }
}
api.collider({kind: 'box', halfExtents: [half, 0.7, W / 2], offset: [0, deckY, 0]});
return api.build();
